ST.xhtml:
IF RawIn >= Neutral THEN
    Delta := INT_TO_REAL(10000 - Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
ELSE
    Delta := INT_TO_REAL(Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
END_IF;

IF ABS(OutPct) <= Deadband THEN
    OutPct := 0.0;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Brake) ===

// 🛑 1. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
        State := E_State.DONE;
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
        State := E_State.BUSY;
    END_IF;
ELSE
    // 🆕 REX 2026-07-08 : Sécurité positive - fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY);
Done := (State = E_State.DONE);

// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (NOT BrakeCmd AND ContactorFeedback);  // commandé collé mais retour "relâché"
        ContactorCheck.StuckOpen   := (BrakeCmd AND NOT ContactorFeedback);  // commandé relâché mais retour "collé"
        ErrorId := ErrorId OR 16#0001;
    ELSIF ResetEdge.Q THEN
        ContactorCheck.StuckClosed := FALSE;
        ContactorCheck.StuckOpen   := FALSE;
        ErrorId := ErrorId AND 16#FFFE;
    END_IF;
ELSE
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
    ErrorId := ErrorId AND 16#FFFE;   // Bypass actif : efface/maintient à 0 le bit 0
END_IF;

// 🧾 5. ARBITRAGE ERROR / STATEATERROR (figé jusqu'à acquittement)
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🛡️ 6. SORTIE SÛRE SUR DÉFAUT (Partie3 §9 étape 7 — ajout revue de code 2026-07-01)
// Incohérence commande/retour détectée : on ne peut plus se fier à la séquence temporisée
// normale (le contacteur suspect biaiserait la logique) → position sûre par défaut (collé).
IF Error THEN
    BrakeCmd := FALSE;
END_IF;

// === IMPLEMENTATION (SQUELETTE — corps à compléter/vérifier avant collage, voir TBD en tête de fichier) ===

// 🛑 1. GATE (Enable / EmergencyStopOk) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT EmergencyStopOk THEN
    RelayFwd := FALSE; RelayRev := FALSE; RelaySpeedGv := FALSE;
    DriveControlWord := 0; DriveFreqRefHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeCmd := Brake.BrakeCmd;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ApproachTimer(IN := FALSE, PT := ApproachTime);
    SpeedRamp(Target := 0.0, AccelRate := RampAccelRate, DecelRate := RampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;
    DegradedMoveAuthorized := FALSE;
    DegradedStopSettleTon(IN := FALSE, PT := DegradedStopSettleTime);
    CommModeLocked := CommMode;   // Neutralisé = libre de choisir le mode (pas de mouvement en cours)

    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms (valeur de secours si delta temps invalide)

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔒 2bis. GARDE CommMode — 🆕 v1.1 (F5) : pas de changement de mode de communication en cours
// de mouvement. Utilise Busy du cycle PRÉCÉDENT (pas encore recalculé ce cycle, §9) : tant que
// l'axe était en mouvement au dernier scan, CommMode externe est ignoré.
IF NOT Busy THEN
    CommModeLocked := CommMode;
END_IF;

// 📡 3. CAPTEUR POSITION CIBLE (debounce commun aux 2 modes)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop THEN
    RampTargetPct := ABS(SpeedRefPct);  // 🔧 2026-07-02 : SpeedRefPct peut arriver signé (AxisCmdX.SpeedRef) — ABS() ici
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE — ETHERCAT uniquement (Partie4 §5)
// DEGRADED_IO : pas d'automatisme, le choix PV/GV reste manuel (joystick) — voir §5bis
IF CommModeLocked = E_ChariotCommMode.ETHERCAT THEN
    ApproachTimer(IN := (StartStop AND NOT SafeStop), PT := ApproachTime);
    IF ApproachTimer.Q THEN
        RampTargetPct := LIMIT(0.0, RampTargetPct, ApproachSpeedPct);
    END_IF;
ELSE
    ApproachTimer(IN := FALSE, PT := ApproachTime);
END_IF;

// 🎯 4ter. ARRÊT EXACT SUR CAPTEUR — §9bis (commun aux 2 modes, comportement PROPOSÉ à valider)
// Verrouille (ArrivalLock) tant que le capteur cible reste actif ET que le sens commandé est
// le MÊME que celui qui a mené à l'arrivée (permet de repartir immédiatement en sens inverse,
// contrairement à un blocage total qui empêcherait de quitter la position).
ArrivalEdge(CLK := TargetReached);
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;
ArrivalLock := TargetReached AND (Direction = DirectionAtArrival) AND (DirectionAtArrival <> 0);
IF ArrivalLock THEN
    RampTargetPct := 0.0;   // Pertinent en ETHERCAT (consigne proportionnelle) ; sans effet direct en DEGRADED_IO, voir §5bis/DegradedMoveAuthorized
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := RampAccelRate,
          DecelRate := SEL(SafeStop, RampDecelNormalRate, RampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

// ⏱️ 4quater. CONFIRMATION D'ARRÊT PHYSIQUE — 🆕 v1.1 (F1)
// DEGRADED_IO : basée sur un délai RÉEL depuis la coupure du relais (RelayFwd/RelayRev tiennent
// encore la valeur du cycle précédent à ce stade — pas encore recalculés, voir §5bis), PAS sur
// la rampe logicielle SpeedRamp (sans lien physique en DEGRADED_IO, cf. correctif F1 en tête de fichier).
DegradedStopSettleTon(IN := NOT (RelayFwd OR RelayRev), PT := DegradedStopSettleTime);
IsStoppedConfirmed := SEL(CommModeLocked = E_ChariotCommMode.DEGRADED_IO,
                          (ABS(SpeedRamp.Current) < 0.1),   // ETHERCAT : rampe = consigne réelle
                          DegradedStopSettleTon.Q);          // DEGRADED_IO : délai physique réel

// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (même principe que FB_Winch §3bis)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF IsStoppedConfirmed THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

// 🆕 v1.1 (F1) — Autorisation de mouvement DEGRADED_IO : IMMÉDIATE, découplée de la rampe logicielle
DegradedMoveAuthorized := StartStop AND NOT SafeStop AND NOT ArrivalLock;

MovementRequested := SEL(CommModeLocked = E_ChariotCommMode.DEGRADED_IO,
                          (CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1),  // ETHERCAT : lié à la rampe réelle (pilote le frein en douceur)
                          (CommandedDirection <> 0) AND DegradedMoveAuthorized);          // DEGRADED_IO : immédiat

// 🔀 5bis. SORTIE PHYSIQUE SELON CommModeLocked
IF CommModeLocked = E_ChariotCommMode.ETHERCAT THEN
    RelayFwd := FALSE; RelayRev := FALSE; RelaySpeedGv := FALSE;

    // 🔴 TBD — mise à l'échelle %→Hz : calcul linéaire explicite (LIN_TRAFO NON vérifié, voir tête de fichier)
    DriveFreqRefHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;
    // 🔴 TBD — DriveControlWord : layout de bits non disponible à la rédaction (Run/Stop/Enable/Reset
    // variateur selon protocole AC600 — À CONFIRMER avant tout collage, ne pas déduire de bits ici).
    DriveControlWord := 0;

    HystGv(IN := 0, HIGH := 0, LOW := 0);   // Inerte en ETHERCAT — instance maintenue pour cohérence cyclique
ELSE // DEGRADED_IO
    DriveFreqRefHz := 0.0;
    DriveControlWord := 0;

    // 🪜 Sélection PV/GV par HYSTERESIS (lib Util, Partie3 §0) — anti-battement, PAS de FB_SpeedStep
    // (table 5 paliers disproportionnée pour un choix à 2 états)
    // 🔧 2026-07-02 : ABS() — SpeedRefPct signé, les seuils Threshold sont des seuils de MAGNITUDE
    // (60%/40%) ; sans ABS() une consigne négative (sens arrière) ne dépasserait jamais HIGH et
    // resterait bloquée en PV quelle que soit la vitesse réelle demandée en marche arrière.
    SpeedRefInt := REAL_TO_INT(ABS(SpeedRefPct));
    HystGv(IN := SpeedRefInt, HIGH := REAL_TO_INT(DegradedGvThresholdHighPct), LOW := REAL_TO_INT(DegradedGvThresholdLowPct));
    RelaySpeedGv := NOT HystGv.OUT;   // Convention FB_SpeedStep : OUT=TRUE en régime bas → NOT OUT = seuil haut franchi (GV)

    // 🆕 v1.1 (F1) — coupure IMMÉDIATE sur DegradedMoveAuthorized=FALSE (StartStop=FALSE, SafeStop,
    // ou ArrivalLock) : ne dépend plus du temps de décroissance de la rampe logicielle.
    RelayFwd := (CommandedDirection = 1) AND DegradedMoveAuthorized;
    RelayRev := (CommandedDirection = -1) AND DegradedMoveAuthorized;
END_IF;

// 🛑 6. FREIN (composé, réutilisé tel quel) — indépendant du mode
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeCmd := Brake.BrakeCmd;
BrakeContactorCheck := Brake.ContactorCheck;

// 🔍 7. DOUBLE VÉRIFICATION CONTACTEURS DE SENS — pertinent en DEGRADED_IO uniquement
// (en ETHERCAT, RelayFwd/RelayRev restent FALSE ci-dessus, donc pas de fausse incohérence
// tant que les retours câblés lisent bien FALSE au repos)
FwdContactorCheck.Command := RelayFwd;
FwdContactorCheck.Feedback := ContactorFeedbackFwd;
TonFwdFeedback(IN := (RelayFwd <> ContactorFeedbackFwd), PT := ContactorFeedbackTimeout);
IF TonFwdFeedback.Q THEN
    FwdContactorCheck.StuckClosed := (NOT RelayFwd AND ContactorFeedbackFwd);
    FwdContactorCheck.StuckOpen   := (RelayFwd AND NOT ContactorFeedbackFwd);
ELSIF ResetEdge.Q THEN
    FwdContactorCheck.StuckClosed := FALSE; FwdContactorCheck.StuckOpen := FALSE;
END_IF;

RevContactorCheck.Command := RelayRev;
RevContactorCheck.Feedback := ContactorFeedbackRev;
TonRevFeedback(IN := (RelayRev <> ContactorFeedbackRev), PT := ContactorFeedbackTimeout);
IF TonRevFeedback.Q THEN
    RevContactorCheck.StuckClosed := (NOT RelayRev AND ContactorFeedbackRev);
    RevContactorCheck.StuckOpen   := (RelayRev AND NOT ContactorFeedbackRev);
ELSIF ResetEdge.Q THEN
    RevContactorCheck.StuckClosed := FALSE; RevContactorCheck.StuckOpen := FALSE;
END_IF;

// 🧾 8. ERRORID (bitfield, cumul — effacé bit à bit si cause disparue + reset front)
IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🧪 Simulation (GVL_Simulation.ContactorFeedbackM3_IsReal, passé par l'appelant via
// BypassContactorCheck, même principe que FB_Winch) — sans contacteurs réels câblés/
// cohérents en essai, StuckClosed/StuckOpen bloque à tort RelayFwd/RelayRev.
IF NOT BypassContactorCheck THEN
    IF FwdContactorCheck.StuckClosed OR FwdContactorCheck.StuckOpen THEN
        ErrorId := ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;

    IF RevContactorCheck.StuckClosed OR RevContactorCheck.StuckOpen THEN
        ErrorId := ErrorId OR 16#0004;
    ELSIF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFB;
    END_IF;
ELSE
    ErrorId := ErrorId AND 16#FFF9;   // Bypass actif : efface/maintient à 0 les bits 1/2
END_IF;

// 🔴 TBD — bit3 défaut variateur : uniquement basé sur DriveFaultFeedback TOR SI câblé (ne
// jamais stubber ce bit si le retour n'existe pas encore — cf. principe codeur TBD FB_Safety_Winch)
IF DriveFaultFeedback THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🚦 9. STATE MACHINE (phase — orthogonale à Error, Partie3 §2)
// ⚠️ En DEGRADED_IO, cet indicateur reste basé sur SpeedRamp.Current (valeur logicielle sans lien
// physique direct, cf. F7) : usage diagnostic/IHM uniquement, PAS utilisé pour une décision de
// sécurité (celles-ci utilisent DegradedMoveAuthorized/IsStoppedConfirmed, calculés séparément).
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING) OR RelayFwd OR RelayRev;

Done := FALSE;   // Pas de notion de "terminé" ponctuel sans FB_Cycle — présent pour conformité

// 🛡️ 10. SORTIE SÛRE SUR DÉFAUT (Partie3 §9 étape 7)
IF Error THEN
    RelayFwd := FALSE; RelayRev := FALSE; RelaySpeedGv := FALSE;
    DriveControlWord := 0; DriveFreqRefHz := 0.0;
    BrakeCmd := FALSE;
END_IF;

// === IMPLEMENTATION ===

// 🛑 1. GATES DE SÉCURITÉ ET BLOCAGE
IF NOT Enable OR NOT EmergencyStopOk THEN
    CmdWinchM1_StartStop := FALSE;
    CmdWinchM1_Direction := 0;
    CmdWinchM1_SpeedPct  := 0.0;

    CmdWinchM2_StartStop := FALSE;
    CmdWinchM2_Direction := 0;
    CmdWinchM2_SpeedPct  := 0.0;

    CmdChariotM3_Start   := FALSE;
    CmdChariotM3_Target  := 0;
    CmdGrappin_Open      := FALSE;
    CmdGrappin_Close     := FALSE;

    State                := E_CycleStep.INIT;
    CycleStep            := E_CycleStep.INIT;
    CycleStateStr        := 'ARRÊT : SÉCURITÉ ABSENTE OU AUTO DÉSACTIVÉ';
    Ready                := FALSE;
    Busy                 := FALSE;
    Done                 := FALSE;
    IsPaused             := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
PauseEdge(CLK := PauseCycle);
AbortEdge(CLK := AbortCycle);

// Gestion de la Pause
IF PauseEdge.Q AND Busy AND NOT IsPaused THEN
    IsPaused := TRUE;
    SavedState := State;
    State := E_CycleStep.ERROR_HOLD; // Fige les mouvements
ELSIF StartEdge.Q AND IsPaused THEN
    IsPaused := FALSE;
    State := SavedState; // Reprise à l'étape sauvegardée
END_IF;

// Gestion de l'Abandon
IF AbortEdge.Q THEN
    IsPaused := FALSE;
    State := E_CycleStep.INIT;
END_IF;

// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état)
CASE State OF

    E_CycleStep.INIT: // 🔄 ÉTAPE 0 : Initialisation et vérifications
        CycleStep := E_CycleStep.INIT;
        CycleStateStr := 'VÉRIFICATION COHÉRENCE SYSTÈME';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;
        CmdChariotM3_Start   := FALSE;
        CmdGrappin_Open      := FALSE;
        CmdGrappin_Close     := FALSE;
        Busy                 := FALSE;
        Done                 := FALSE;

        // Transition si système sain et réarmé (front reset ou démarrage)
        IF StartEdge.Q THEN
            State := E_CycleStep.WORK_POS_SELECT;
        END_IF;

    E_CycleStep.WORK_POS_SELECT: // 📍 ÉTAPE 1 : Sélection position travail
        CycleStep := E_CycleStep.WORK_POS_SELECT;
        CycleStateStr := 'SÉLECTION POSITION TRAVAIL (FOSSE 1 / 2)';
        Busy := TRUE;

        // Choix cible
        IF SelectedTargetNum_IHM = 1 OR SelectedTargetNum_IHM = 2 THEN
            SelectedWorkTarget := SelectedTargetNum_IHM;
            CmdChariotM3_Target := SelectedWorkTarget;
            CmdChariotM3_Start := TRUE;

            // Attente positionnement chariot
            IF (SelectedWorkTarget = 1 AND Chariot_At_Fosse1) 
               OR (SelectedWorkTarget = 2 AND Chariot_At_Fosse2) THEN
                CmdChariotM3_Start := FALSE;
                State := E_CycleStep.DESCENDING_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.DESCENDING_OPEN: // ⬇️ ÉTAPE 2 : Plongée grappin ouvert
        CycleStep := E_CycleStep.DESCENDING_OPEN;
        CycleStateStr := 'PLONGÉE GRAPPIN OUVERT';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := -1;
        CmdWinchM1_SpeedPct  := 50.0; // Vitesse de descente 50%

        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := -1;
        CmdWinchM2_SpeedPct  := 50.0;

        // Transition si fond touché (mou de câble détecté)
        IF BottomTouched THEN
            CmdWinchM1_StartStop := FALSE;
            CmdWinchM2_StartStop := FALSE;
            TouchPositionM := M1_CablePosM; // Mémorisation position contact
            State := E_CycleStep.BOTTOM_TOUCH_WAIT;
        END_IF;

    E_CycleStep.BOTTOM_TOUCH_WAIT: // ⏳ ÉTAPE 3 : Temporisation contact fond
        CycleStep := E_CycleStep.BOTTOM_TOUCH_WAIT;
        CycleStateStr := 'ATTENTE DÉPOSE FOND';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;

        // Transition après pose confirmée (ici instantanée, prête pour tempo)
        State := E_CycleStep.SYNCHRO_ADJUST;

    E_CycleStep.SYNCHRO_ADJUST: // 🪣 ÉTAPE 4 : Fermeture du grappin (Excavation)
        CycleStep := E_CycleStep.SYNCHRO_ADJUST;
        CycleStateStr := 'FERMETURE DU GODET / EXCAVATION';

        CmdWinchM1_StartStop := FALSE; // M1 reste immobile

        // Déclenchement fermeture grappin
        CmdGrappin_Close := TRUE;

        // Transition si grappin fermé avec succès
        IF Grappin_Done AND Grappin_IsClosed THEN
            CmdGrappin_Close := FALSE;
            State := E_CycleStep.CTRL_ASCENDING;
        END_IF;

    E_CycleStep.CTRL_ASCENDING: // ⬆️ ÉTAPE 5 : Remontée lente de contrôle
        CycleStep := E_CycleStep.CTRL_ASCENDING;
        CycleStateStr := 'REMONTÉE LENTE DE CONTRÔLE';

        // M1 et M2 montent lentement en synchro
        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := 1;
        CmdWinchM1_SpeedPct  := 20.0; // 20% max

        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := 1;
        CmdWinchM2_SpeedPct  := 20.0;

        // Transition après remontée de contrôle de 2.0 mètres
        IF M1_CablePosM >= (TouchPositionM + CtrlAscentDistM) THEN
            State := E_CycleStep.ASCENDING_LOADED;
        END_IF;

    E_CycleStep.ASCENDING_LOADED: // 🚀 ÉTAPE 6 : Remontée pleine vitesse
        CycleStep := E_CycleStep.ASCENDING_LOADED;
        CycleStateStr := 'REMONTÉE EN CHARGE';

        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := 1;
        CmdWinchM1_SpeedPct  := 70.0; // Grande vitesse 70%

        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := 1;
        CmdWinchM2_SpeedPct  := 70.0;

        // Transition si position haute (butée haute virtuelle) atteinte
        IF M1_CablePosM >= GVL_PERSISTENT.HomingTargetM1_M - 2.0 THEN // -2m de la butée haute
            CmdWinchM1_StartStop := FALSE;
            CmdWinchM2_StartStop := FALSE;
            State := E_CycleStep.DRAINING_PAUSE;
        END_IF;

    E_CycleStep.DRAINING_PAUSE: // 💧 ÉTAPE 7 : Égouttage temporisé
        CycleStep := E_CycleStep.DRAINING_PAUSE;
        CycleStateStr := 'ÉGOUTTAGE DU GODET EN COURS';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        IF DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.CHARIOT_MOVE;
        END_IF;

    E_CycleStep.CHARIOT_MOVE: // ↔️ ÉTAPE 8 : Déplacement vers trémie
        CycleStep := E_CycleStep.CHARIOT_MOVE;
        CycleStateStr := 'DÉPLACEMENT VERS TRÉMIE DE VIDANGE';

        CmdChariotM3_Target := 4; // Trémie
        CmdChariotM3_Start := TRUE;

        // Transition si chariot arrivé à la trémie
        IF Chariot_At_Tremie THEN
            CmdChariotM3_Start := FALSE;
            State := E_CycleStep.DESCENDING_OPEN_DUMP;
        END_IF;

    E_CycleStep.DESCENDING_OPEN_DUMP: // 🗑️ ÉTAPE 9 : Ouverture grappin (Vidange)
        CycleStep := E_CycleStep.DESCENDING_OPEN_DUMP;
        CycleStateStr := 'VIDANGE / OUVERTURE DU GODET';

        // Déclenchement ouverture grappin
        CmdGrappin_Open := TRUE;

        // Transition si grappin ouvert avec succès
        IF Grappin_Done AND Grappin_IsOpen THEN
            CmdGrappin_Open := FALSE;
            State := E_CycleStep.RETURN_WORK_POS;
        END_IF;

    E_CycleStep.RETURN_WORK_POS: // 🔙 ÉTAPE 10 : Retour fosse de travail
        CycleStep := E_CycleStep.RETURN_WORK_POS;
        CycleStateStr := 'RETOUR VERS FOSSE DE TRAVAIL';

        CmdChariotM3_Target := SelectedWorkTarget;
        CmdChariotM3_Start := TRUE;

        // Transition si chariot de retour sur sa fosse
        IF (SelectedWorkTarget = 1 AND Chariot_At_Fosse1) 
           OR (SelectedWorkTarget = 2 AND Chariot_At_Fosse2) THEN
            CmdChariotM3_Start := FALSE;
            State := E_CycleStep.READY;
        END_IF;

    E_CycleStep.READY: // 🏁 ÉTAPE 11 : Prêt / Cycle terminé
        CycleStep := E_CycleStep.READY;
        CycleStateStr := 'CYCLE AUTOMATIQUE COMPLÉTÉ - PRÊT';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;
        CmdChariotM3_Start   := FALSE;
        Done                 := TRUE;
        Busy                 := FALSE;

        // Rebouclage manuel ou auto sur Start
        IF StartEdge.Q THEN
            Done := FALSE;
            State := E_CycleStep.DESCENDING_OPEN;
        END_IF;

    E_CycleStep.ERROR_HOLD: // 🛑 ÉTAPE 12 : Maintien sur arrêt / pause
        CycleStep := E_CycleStep.ERROR_HOLD;
        CycleStateStr := 'CYCLE SUSPENDU (PAUSE OU ARRÊT DE SÉCURITÉ)';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;
        CmdChariotM3_Start   := FALSE;

        // Relâchement des commandes grappin
        CmdGrappin_Open := FALSE;
        CmdGrappin_Close := FALSE;
END_CASE;

// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();

// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;

// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);

// 4. CONVERSION ET CHARGE DE SECOURS
IF DeltaTimeMs > 0 THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;

// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;

// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_DiagState.DISABLED;
    Joystick.State := E_DiagState.DISABLED;
    Joystick.Online := FALSE;
    Joystick.Operational := FALSE;
    Joystick.Error := FALSE;
    Joystick.ErrorId := 16#0000;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CanOnline AND CanOperational) THEN
        Joystick.ErrorId := 16#0000;
        StateAtError := E_DiagState.DISABLED;
    END_IF;
END_IF;

// 🔍 3. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CanOnline THEN
    Joystick.ErrorId := 16#0001;  (* Perte liaison CAN joystick *)
    Joystick.Online := FALSE;
ELSE
    Joystick.Online := TRUE;
    IF ResetEdge.Q THEN
        Joystick.ErrorId := Joystick.ErrorId AND 16#FFFE;
    END_IF;
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT CanOperational THEN
    Joystick.ErrorId := Joystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    Joystick.Operational := FALSE;
ELSE
    Joystick.Operational := TRUE;
    IF ResetEdge.Q THEN
        Joystick.ErrorId := Joystick.ErrorId AND 16#FFFD;
    END_IF;
END_IF;

// 🚦 4. MACHINE D'ÉTAT JOYSTICK
IF Joystick.ErrorId <> 0 THEN
    Joystick.State := E_DiagState.ERROR;
    IF StateAtError = E_DiagState.DISABLED THEN
        StateAtError := State;
    END_IF;
ELSIF NOT (Joystick.Online AND Joystick.Operational) THEN
    Joystick.State := E_DiagState.INIT;
else
    Joystick.State := E_DiagState.READY;
END_IF;

State := Joystick.State;

// 📤 5. SORTIES GLOBALES
Joystick.Error := (Joystick.ErrorId <> 0);
Error := Joystick.Error;
ErrorId := Joystick.ErrorId;

busCanOpen.Operational := CanOnline;
busCanOpen.Online := CanOnline;

// Briques génériques pour conformité standard
Busy := FALSE;
Done := FALSE;

// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_DiagState.DISABLED;
    Variateur.State := E_DiagState.DISABLED;
    EncoderM1.State := E_DiagState.DISABLED;
    EncoderM2.State := E_DiagState.DISABLED;
    Variateur.Online := FALSE;
    EncoderM1.Online := FALSE;
    EncoderM2.Online := FALSE;
    Variateur.Operational := FALSE;
    EncoderM1.Operational := FALSE;
    EncoderM2.Operational := FALSE;
    Variateur.Error := FALSE;
    EncoderM1.Error := FALSE;
    EncoderM2.Error := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
Variateur.Online := NOT VariateurWcState;
Variateur.Operational := Variateur.Online AND (VariateurSlaveState = 8);

IF NOT Variateur.Online THEN
    Variateur.ErrorId := 16#0010;  (* Perte liaison physique variateur *)
ELSE
    IF ResetEdge.Q THEN
        Variateur.ErrorId := Variateur.ErrorId AND 16#FFEF;
    END_IF;
END_IF;

IF NOT Variateur.Operational AND Variateur.Online THEN
    Variateur.ErrorId := Variateur.ErrorId OR 16#0011;  (* Variateur pré-opérationnel *)
ELSE
    IF ResetEdge.Q THEN
        Variateur.ErrorId := Variateur.ErrorId AND 16#FFEE;
    END_IF;
END_IF;

// 🔍 4. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
EncoderM1.Online := NOT EncoderM1WcState;
EncoderM1.Operational := EncoderM1.Online AND (EncoderM1SlaveState = 8);

IF NOT EncoderM1.Online THEN
    EncoderM1.ErrorId := 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    IF ResetEdge.Q THEN
        EncoderM1.ErrorId := EncoderM1.ErrorId AND 16#FFDF;
    END_IF;
END_IF;

IF NOT EncoderM1.Operational AND EncoderM1.Online THEN
    EncoderM1.ErrorId := EncoderM1.ErrorId OR 16#0021;  (* Encodeur M1 pré-opérationnel *)
ELSE
    IF ResetEdge.Q THEN
        EncoderM1.ErrorId := EncoderM1.ErrorId AND 16#FFDE;
    END_IF;
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
EncoderM2.Online := NOT EncoderM2WcState;
EncoderM2.Operational := EncoderM2.Online AND (EncoderM2SlaveState = 8);

IF NOT EncoderM2.Online THEN
    EncoderM2.ErrorId := 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    IF ResetEdge.Q THEN
        EncoderM2.ErrorId := EncoderM2.ErrorId AND 16#FFCF;
    END_IF;
END_IF;

IF NOT EncoderM2.Operational AND EncoderM2.Online THEN
    EncoderM2.ErrorId := EncoderM2.ErrorId OR 16#0031;  (* Encodeur M2 pré-opérationnel *)
ELSE
    IF ResetEdge.Q THEN
        EncoderM2.ErrorId := EncoderM2.ErrorId AND 16#FFCE;
    END_IF;
END_IF;

// 🚦 6. STATE MACHINES DE CHAQUE APPAREIL
IF Variateur.ErrorId <> 0 THEN
    Variateur.State := E_DiagState.ERROR;
ELSIF NOT Variateur.Online THEN
    Variateur.State := E_DiagState.INIT;
ELSIF Variateur.Operational THEN
    Variateur.State := E_DiagState.READY;
ELSE
    Variateur.State := E_DiagState.MONITORING;
END_IF;

IF EncoderM1.ErrorId <> 0 THEN
    EncoderM1.State := E_DiagState.ERROR;
ELSIF NOT EncoderM1.Online THEN
    EncoderM1.State := E_DiagState.INIT;
ELSIF EncoderM1.Operational THEN
    EncoderM1.State := E_DiagState.READY;
ELSE
    EncoderM1.State := E_DiagState.MONITORING;
END_IF;

IF EncoderM2.ErrorId <> 0 THEN
    EncoderM2.State := E_DiagState.ERROR;
ELSIF NOT EncoderM2.Online THEN
    EncoderM2.State := E_DiagState.INIT;
ELSIF EncoderM2.Operational THEN
    EncoderM2.State := E_DiagState.READY;
ELSE
    EncoderM2.State := E_DiagState.MONITORING;
END_IF;

// Fige la phase du diagnostic global sur le premier défaut
IF (Variateur.ErrorId <> 0 OR EncoderM1.ErrorId <> 0 OR EncoderM2.ErrorId <> 0) THEN
    IF StateAtError = E_DiagState.DISABLED THEN
        StateAtError := State;
    END_IF;
END_IF;

// 📤 7. RÉSUMÉ ET DÉFAUTS
Variateur.Error := (Variateur.ErrorId <> 0);
EncoderM1.Error := (EncoderM1.ErrorId <> 0);
EncoderM2.Error := (EncoderM2.ErrorId <> 0);

Error := (Variateur.Error OR EncoderM1.Error OR EncoderM2.Error);

ErrorId := 16#0000;
IF Variateur.Error THEN
    ErrorId := ErrorId OR 16#00F0;
END_IF;
IF EncoderM1.Error THEN
    ErrorId := ErrorId OR 16#0F00;
END_IF;
IF EncoderM2.Error THEN
    ErrorId := ErrorId OR 16#F000;
END_IF;

IF Error THEN
    State := E_DiagState.ERROR;
ELSIF NOT (Variateur.Operational AND EncoderM1.Operational AND EncoderM2.Operational) THEN
    State := E_DiagState.MONITORING;
ELSE
    State := E_DiagState.READY;
END_IF;

BusEthercat.Online := Variateur.Online AND EncoderM1.Online AND EncoderM2.Online;
BusEthercat.Operational := Variateur.Operational AND EncoderM1.Operational AND EncoderM2.Operational;

Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;
EncoderAvailable := (ErrorId AND 16#0001) = 0;

// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // 🔧 2026-07-03 : sens de comptage géré côté codeur (CoE 6000h bit0,
                          // startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;

// 🔧 5. SÉQUENCE PRESET (écriture bus)
// ✅ Confirmé terrain (2026-07-02) : PresettTrigCmd := 2 déclenche le référencement à
//    PresetValue (valeur de commande, pas un masque de bits — corrige l'hypothèse initiale).
// 🔴 CodeSeqTrigCmd : rôle NON identifié (même par l'utilisateur/terrain) — laissé à 0,
//    PAS piloté tant que sa fonction n'est pas confirmée (fiche technique ou essai dédié).
//    Ne jamais lui donner une valeur arbitraire "au cas où".
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // 🔴 non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (1 cycle suffit normalement, laissé actif jusqu'à confirmation)
        PresetTriggerCmd := 2;   // ✅ Valeur confirmée terrain — référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTriggerCmd := 0;
            PresetAck := TRUE;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            ErrorId := ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧾 6. ERROR / STATEATERROR
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := (PresetSeqStep <> 0);
Done := PresetAck;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := ConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            ErrorId := ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF State = E_State.INIT THEN State := E_State.READY; END_IF;
END_IF;

// ✅ 4. LEVÉE DU DOUTE (ConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) THEN
    Calib.HomingSuspect := FALSE;
    ErrorId := ErrorId AND 16#FDFF;   // efface bit9
END_IF;

// 🎯 5. DEMANDE DE RÉFÉRENCEMENT (flux nominal)
// ⚠️ `TopSensorPositionM` n'est PAS revalidée contre le bornage [-99.00;+99.00] m (§3.6) dans ce
// lot : c'est un paramètre RETAIN de mise en service (comme CableM_PerRev/PointsPerRev), pas une
// saisie opérateur par requête — valeur indicative ≈12.50 m largement dans la plage.
// 🔧 REX 2026-07-07 : FwdRevSpeedFeedbackOff remplace (NOT ContactorFeedbackFwd) AND (NOT ContactorFeedbackRev)
ArretConfirme := FwdRevSpeedFeedbackOff AND BrakeFeedback;

PresetRequest := FALSE;   // Défaut chaque cycle — repose uniquement sur le front HomeEdge ci-dessous
IF HomeEdge.Q AND (State <> E_State.BUSY) THEN
    // ✅ Homing autorisé en MAINT_N1 et MAINT_N2 — interdit en SEMI_AUTO et en cycle AUTO
    IF (Mode <> E_Mode.MAINT_N1) AND (Mode <> E_Mode.MAINT_N2) THEN
        ErrorId := ErrorId OR 16#0001;        // bit0 : mode non autorisé (seulement MAINT N1/N2)
    ELSIF NOT EncoderAvailable THEN
        ErrorId := ErrorId OR 16#0008;        // bit3 : codeur indisponible
    ELSIF NOT ArretConfirme THEN
        ErrorId := ErrorId OR 16#0004;        // bit2 : arrêt non confirmé (contacteurs/frein)
    ELSIF (Mode <> E_Mode.MAINT_N2) AND TopPositionSensor THEN
        // 🔧 CORRIGÉ 2026-07-04 : polarité inversée (testait NOT TopPositionSensor). Convention
        // NAMING_CONVENTION.md : TRUE = sain/non atteint, FALSE = position haute confirmée
        // (contact ouvert) — le Home nominal doit être rejeté tant que TopPositionSensor=TRUE.
        ErrorId := ErrorId OR 16#0010;        // bit4 : capteur position haute non confirmé (requis uniquement en MAINT_N1)
    ELSE
        // ✅ Toutes conditions réunies : calcul de la cible brute et déclenchement
        PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;               // Centre exact (§3.3)
        TargetPoints := REAL_TO_DINT(TopSensorPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PresetValue := PresetValueCalc;
        PresetRequest := TRUE;                // Pulse 1 cycle — FB_Encoder_Abs détecte le front lui-même
        State := E_State.BUSY;
    END_IF;
END_IF;

// ⏳ 6. SUIVI DE LA SÉQUENCE (BUSY → confirmation)
Done := FALSE;
IF State = E_State.BUSY THEN
    IF PresetAck THEN
        Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(PresetValueCalc) - TargetPoints);
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := PresetValueCalc;
        Done := TRUE;
        State := E_State.READY;
        // 🔧 REX 2026-07-07 : un homing réussi re-établit la référence tout aussi validement
        // qu'un ConfirmCoherence explicite — efface donc aussi bit9 (incohérence redémarrage),
        // sinon ErrorId/Error restait bloqué à TRUE après un homing réussi (jamais mappé vers
        // l'IHM, invisible sauf sur GVL_IHM.Modes.AnyFaultActive qui restait à 1 sans raison visible).
        ErrorId := ErrorId AND 16#FDFF;
    ELSIF PresetNak THEN
        ErrorId := ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFC2;   // efface bits 0,2,3,4,5 (garde bit9, levé seulement par ConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Busy := (State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // 🆕 REX 2026-07-08 : Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après ConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Safety) ===

// 🛑 1. GATE — expose la dernière valeur plausible connue même désactivé
IF NOT Enable THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    CablePosMSafe := LastPlausibleCablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. BORNAGE PHYSIQUE ABSOLU (§3.6) — bit0
IF (CablePosM < PositionMinM) OR (CablePosM > PositionMaxM) THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 4. RELAIS INCOHÉRENCE REDÉMARRAGE (§3.7, calculée par FB_Encoder_Homing) — bit1
// Pas d'acquittement ici : la levée se fait via ConfirmCoherence/nouveau Home côté
// FB_Encoder_Homing (source), ce FB ne fait QUE relayer l'information pour FB_Modes.
IF HomingSuspect THEN
    ErrorId := ErrorId OR 16#0002;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧊 5. GELER SUR DOUTE (§6) — CablePosMSafe ne suit PAS CablePosM si hors plage
IF (ErrorId AND 16#0001) = 16#0000 THEN
    LastPlausibleCablePosM := CablePosM;
END_IF;
CablePosMSafe := LastPlausibleCablePosM;

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

EncoderIncoherent := Error;
Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2)
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;   // Garde division par zéro (PointsPerRev mal configuré)
END_IF;

T := TIME_TO_REAL(TimeConst) / 1000.0; // ms → s

IF T <= 0.0 OR CycleTimeS <= 0.0 THEN
    ValueOut := ValueIn;
ELSE
    Alpha    := CycleTimeS / (T + CycleTimeS);
    ValueOut := Alpha * ValueIn + (1.0 - Alpha) * ValueOut;
END_IF;

// 🛑 1. GATE DE SÉCURITÉ
IF NOT Enable OR NOT EmergencyStopOk THEN
    IF (State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        GrappinState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    State := E_State.DISABLED;
    M1SlipDetected := FALSE; // 🔧 REX 2026-07-07
    // Les requêtes internes sont réinitialisées
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

// 🟢 ÉTAT INITIAL READY SI DISABLED PRÉCÉDEMMENT
IF State = E_State.DISABLED THEN
    State := E_State.READY;
END_IF;

// 🔑 2. GESTION DU RESET (FRONT MONTANT)
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFA; // Efface les bits 0 et 2 (Timeout, Limites)
END_IF;

// 📏 3. DÉTECTION D'INCOHÉRENCE AU BOOT (PREMIER CYCLE API)
IF FirstCycle THEN
    FirstCycle := FALSE;
    IF Config.CoherenceLimitM > 0.01 THEN
        IF GrappinState.IsOpen AND NOT GrappinState.IsClosed THEN
            IF ABS(CablePosM2 - GrappinState.LastPosM2Open) > Config.CoherenceLimitM THEN
                GrappinState.StateIncoherent := TRUE;
            END_IF;
        ELSIF GrappinState.IsClosed AND NOT GrappinState.IsOpen THEN
            IF ABS(CablePosM2 - GrappinState.LastPosM2Close) > Config.CoherenceLimitM THEN
                GrappinState.StateIncoherent := TRUE;
            END_IF;
        ELSE
            // Si l'état n'a jamais été initialisé (les deux FALSE/TRUE), on signale une incohérence
            GrappinState.StateIncoherent := TRUE;
        END_IF;
    ELSE
        // Limite non configurée ou invalide, par précaution on force l'incohérence
        GrappinState.StateIncoherent := TRUE;
    END_IF;
END_IF;

// Met à jour le bit1 d'erreur si incohérence détectée
IF GrappinState.StateIncoherent THEN
    ErrorId := ErrorId OR 16#0002;
    // 🆕 REX 2026-07-08 : Force l'état inconnu (ni ouvert ni fermé) si incohérence active
    GrappinState.IsOpen := FALSE;
    GrappinState.IsClosed := FALSE;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧲 3bis. GARDE-FOU CODEURS NON RÉFÉRENCÉS (bit 3) — REX 2026-07-07
// CablePosM1/CablePosM2 ne sont fiables que si le homing (Partie10) a été fait sur les 2 treuils.
// Continu (pas de front Reset) : se lève/efface tout seul selon l'état réel du homing.
IF NOT HomedM1 OR NOT HomedM2 THEN
    ErrorId := ErrorId OR 16#0008;
ELSE
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🆕 3bis-bis. CONFIRMATION MANUELLE POSITION OUVERTE (mise en service, REX 2026-07-08) — voir bandeau
// Action de CONFIRMATION pure (aucun mouvement, ne pilote pas M2) : mémorise GrappinState.IsOpen
// directement, à utiliser juste après le référencement des codeurs (M1=M2, grappin physiquement
// ouvert vérifié par l'opérateur). Gardée comme ConfirmCoherence (FB_Encoder_Homing) : front,
// MAINT_N1/N2 uniquement, codeurs déjà référencés, treuils à l'arrêt (pas de séquence en cours).
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    GrappinState.IsOpen := TRUE;
    GrappinState.IsClosed := FALSE;
    GrappinState.LastPosM2Open := CablePosM2;
    GrappinState.LastPosM2Close := CablePosM2 - Config.OffsetOpenM + Config.OffsetCloseM; // 🆕 Initialisation théorique cohérente avec les offsets configurés
    GrappinState.StateIncoherent := FALSE;
    ErrorId := 16#0000;             // 🆕 REX 2026-07-08 : Réinitialisation complète des défauts grappin lors du référencement manuel
    CloseReq := FALSE;              // 🆕 REX 2026-07-08 : Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 🆕 3bis-ter. CONFIRMATION MANUELLE POSITION FERMÉE (mise en service, REX 2026-07-08)
// Même principe que ConfirmOpenPosition, mais pour initialiser le grappin comme FERMÉ.
ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    GrappinState.IsOpen := FALSE;
    GrappinState.IsClosed := TRUE;
    GrappinState.LastPosM2Close := CablePosM2;
    GrappinState.LastPosM2Open := CablePosM2 - Config.OffsetCloseM + Config.OffsetOpenM; // 🆕 Initialisation théorique cohérente avec les offsets configurés
    GrappinState.StateIncoherent := FALSE;
    ErrorId := 16#0000;             // 🆕 REX 2026-07-08 : Réinitialisation complète des défauts grappin lors du référencement manuel
    CloseReq := FALSE;              // 🆕 REX 2026-07-08 : Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 🔍 3ter. MÉCA C COUCHE 1 — GLISSEMENT M1 PENDANT BUSY (bit4) — REX 2026-07-07
// M1 doit rester immobile pendant que M2 bouge seul. Référence prise à l'entrée en Busy.
BusyEdge(CLK := (State = E_State.BUSY));
IF BusyEdge.Q THEN
    M1RefPosM := CablePosM1;
    M2StartPosM := CablePosM2;   // 🆕 REX 2026-07-08 — borne le recul autorisé (voir §6 CASE BUSY)
    // 🆕 REX 2026-07-08 (demande utilisateur) : mémorise l'état d'origine (restauré si recul complet
    // jusqu'à M2StartPosM, voir §6 CASE BUSY) puis passe en position transitoire dès le démarrage du
    // mouvement — ni ouvert ni fermé pendant le trajet, quel que soit l'état mémorisé avant.
    WasOpenAtStart := GrappinState.IsOpen;
    WasClosedAtStart := GrappinState.IsClosed;
    LeftStartSinceArm := FALSE;
    GrappinState.IsOpen := FALSE;
    GrappinState.IsClosed := FALSE;
END_IF;

IF (State = E_State.BUSY) AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM) AND NOT InhibitM1 THEN
    ErrorId := ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFEF;
END_IF;
M1SlipDetected := (ErrorId AND 16#0010) <> 16#0000;

// 🚨 4. SURVEILLANCE DES LIMITES DE PLACEMENT (Limites dépassées - bit 2)
// On s'assure que l'écart réel M1/M2 ne dépasse pas les offsets de configuration + marge de sécurité de 1m
MaxAllowedOffset := MAX(ABS(Config.OffsetOpenM), ABS(Config.OffsetCloseM)) + 1.0;
IF (ABS(CablePosM1 - CablePosM2) > MaxAllowedOffset) AND NOT InhibitM1 AND NOT InhibitM2 THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// ⏲️ 5. SURVEILLANCE TIMEOUT MOUVEMENT (bit 0)
// Déclenche si le mouvement actif (M2_StartStop = TRUE) dure plus longtemps que le timeout
TonTimeout(IN := (State = E_State.BUSY AND M2_StartStop), PT := TimeoutDuration);
IF TonTimeout.Q THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;

// ❌ Évaluation des erreurs graves (Timeout, Limites dépassées, Codeur(s) non référencé(s), ou Glissement M1)
SevereError := (ErrorId AND 16#001D) <> 16#0000;

IF SevereError THEN
    IF (State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        GrappinState.StateIncoherent := TRUE;
    END_IF;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    // On repasse en READY et attend un Reset
    State := E_State.READY;
END_IF;

// 🎛️ 6. MACHINE À ÉTATS DE COMMANDE
CASE State OF
    E_State.READY:
        Ready := TRUE;
        Busy := FALSE;
        Done := FALSE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // 🔧 REX 2026-07-07 : pas de mouvement en cours

        // 🆕 REX 2026-07-08 : demande grappin acceptée UNIQUEMENT si M1 ET M2 sont à l'arrêt (tous
        // modes) — évite qu'un mouvement en cours sur l'un des deux treuils "traverse" l'armement
        // du grappin (audit sécurité). Ni mémorisation de la requête, ni démarrage tant que ce
        // n'est pas vrai — l'opérateur doit refaire la demande une fois les treuils arrêtés.
        IF NOT M1_Busy AND NOT M2_Busy THEN
            // Mémorisation des requêtes IHM (l'une annule l'autre)
            IF CmdClose_IHM AND NOT SevereError THEN
                CloseReq := TRUE;
                OpenReq := FALSE;
            ELSIF CmdOpen_IHM AND NOT SevereError THEN
                OpenReq := TRUE;
                CloseReq := FALSE;
            END_IF;

            // Condition d'activation du mouvement (Requête IHM + Validation Joystick dans le bon sens)
            // ⚠️ REX 2026-07-07 : sens inversés (enroulage ferme désormais, déroulage ouvre)
            IF CloseReq AND JoystickY_StartStop AND (JoystickY_Direction = 1) THEN
                State := E_State.BUSY;
            ELSIF OpenReq AND JoystickY_StartStop AND (JoystickY_Direction = -1) THEN
                State := E_State.BUSY;
            END_IF;
        END_IF;

    E_State.BUSY:
        Ready := TRUE;
        Busy := TRUE;
        Done := FALSE;
        M2_ForceSlowSpeed := TRUE; // Vitesse lente forcée sans contacteurs

        // 📏 REX 2026-07-07 : distance restante avant cible, pour affichage IHM (aiguille/jauge)
        // Toujours positive, décroît vers 0 à mesure que M2 approche la cible.
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
        ELSE
            RemainingTravelM := 0.0;
        END_IF;

        // Interlock Homme-mort joystick
        // 🆕 REX 2026-07-08 : sens inverse autorisé (recul/annulation partielle) pendant CloseReq/
        // OpenReq, mais BORNÉ à la position de départ (M2StartPosM, mémorisée à l'entrée en Busy) —
        // ne permet jamais de dépasser cette position dans le sens opposé au sens principal.
        IF NOT JoystickY_StartStop THEN
            // Si relâchement du joystick, arrêt temporaire du mouvement
            M2_StartStop := FALSE;
            M2_Direction := 0;
        ELSIF CloseReq THEN
            IF (JoystickY_Direction = 1) THEN
                // Sens principal (fermeture) : M2 enroule (monte) — REX 2026-07-07
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSIF (JoystickY_Direction = -1) AND (CablePosM2 > M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de ré-ouverture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSE
                // Mauvais sens, ou position de départ déjà atteinte en reculant : arrêt
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSIF OpenReq THEN
            IF (JoystickY_Direction = -1) THEN
                // Sens principal (ouverture) : M2 déroule (descend) — REX 2026-07-07
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSIF (JoystickY_Direction = 1) AND (CablePosM2 < M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de re-fermeture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSE
            M2_StartStop := FALSE;
            M2_Direction := 0;
        END_IF;

        // 🆕 REX 2026-07-08 : détecte qu'on a réellement quitté la position de départ (évite que le
        // test de retour ci-dessous ne se déclenche instantanément au 1er cycle de Busy, où
        // CablePosM2 = M2StartPosM par définition).
        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Condition d'arrêt automatique de la fermeture
        IF CloseReq THEN
            // Cible atteinte : M2 a assez enroulé (CablePosM2 croissant) — REX 2026-07-07
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique fermé
                GrappinState.IsOpen := FALSE;
                GrappinState.IsClosed := TRUE;
                GrappinState.LastPosM2Close := CablePosM2;
                GrappinState.StateIncoherent := FALSE; // recalage réussi

                CloseReq := FALSE;
                State := E_State.DONE;
            // 🆕 REX 2026-07-08 (demande utilisateur) : recul complet jusqu'à la position de départ —
            // restaure l'état d'origine (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                GrappinState.IsOpen := WasOpenAtStart;
                GrappinState.IsClosed := WasClosedAtStart;

                CloseReq := FALSE;
                State := E_State.DONE;
            END_IF;
        END_IF;

        // Condition d'arrêt automatique de l'ouverture
        IF OpenReq THEN
            // Cible atteinte : M2 a assez déroulé (CablePosM2 décroissant) — REX 2026-07-07
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique ouvert
                GrappinState.IsOpen := TRUE;
                GrappinState.IsClosed := FALSE;
                GrappinState.LastPosM2Open := CablePosM2;
                GrappinState.StateIncoherent := FALSE; // recalage réussi

                OpenReq := FALSE;
                State := E_State.DONE;
            // 🆕 REX 2026-07-08 (demande utilisateur) : recul complet jusqu'à la position de départ —
            // restaure l'état d'origine (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                GrappinState.IsOpen := WasOpenAtStart;
                GrappinState.IsClosed := WasClosedAtStart;

                OpenReq := FALSE;
                State := E_State.DONE;
            END_IF;
        END_IF;

    E_State.DONE:
        Ready := TRUE;
        Busy := FALSE;
        Done := TRUE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // 🔧 REX 2026-07-07 : cible atteinte

        // Attente du relâchement de la validation joystick pour repasser à READY
        IF NOT JoystickY_StartStop THEN
            State := E_State.READY;
        END_IF;
END_CASE;

// 📤 7. GESTION DES SORTIES D'ÉTAT GLOBALES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Détermination de l'offset actif pour le synchronisme de FB_WinchSync ET pour l'affichage IHM
// (M2PositionCorrected, côté PRG_09_Supervision).
// 🔧 REX 2026-07-08 : ajout de CloseReq/OpenReq (pas seulement IsClosed/IsOpen, qui sont FALSE
// pendant TOUT le trajet depuis le REX du 2026-07-08 sur l'état transitoire) — sinon
// ActiveOffsetM restait figé sur OffsetOpenM (défaut) pendant le trajet entier d'une fermeture,
// donc M2PositionCorrected = CablePosM2 brut tout du long, avec un saut brutal uniquement à
// l'arrivée (constat terrain) au lieu de converger progressivement vers M1 pendant l'enroulage.
IF State = E_State.BUSY THEN
    // 🔧 REX 2026-07-08 : pendant le déplacement, l'offset actif suit la différence réelle
    // de câble (M2 - M1) afin que la position corrigée de M2 reste stable (égale à M1, cad la hauteur du grappin)
    // sans à-coup, tandis que le câble brut de M2 montre son enroulement.
    ActiveOffsetM := CablePosM2 - CablePosM1;
ELSIF CloseReq OR GrappinState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
ELSE
    // Par défaut, ou en cours/état d'ouverture, on applique l'offset ouvert
    ActiveOffsetM := Config.OffsetOpenM;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Input) ===

// 1. Inversion NO/NC
ValueRaw := InputRaw XOR InvertLogic;

// 2. Filtrage anti-rebond — ne valide le changement d'état qu'après FilterTime stable
FilterTon(IN := (ValueRaw <> State), PT := FilterTime);
IF FilterTon.Q THEN
    State := ValueRaw;   // Une fois à jour, IN redevient FALSE au cycle suivant (ValueRaw=State)
END_IF;

// 3. Diagnostic voie/carte
IF NOT ChannelOk THEN
    ErrorId := ErrorId OR 16#0001;
    State := FALSE;   // État sûr forcé (Partie6 §1)
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

Error := (ErrorId <> 16#0000);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Joystick) ===

// 🛑 1. GATE (Sécurités et coupures prioritaires)
IF NOT Enable OR NOT EmergencyStopOk OR NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedRef := 0.0; AxisCmdX.Direction := 0;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedRef := 0.0; AxisCmdY.Direction := 0;
    SpeedXPct := 0.0; DirectionX := 0;
    SpeedYPct := 0.0; DirectionY := 0;
    Button := FALSE;
    DeadmanArmed := FALSE;   // 🆕 Désarmé sur toute neutralisation — nouvel appui au neutre exigé
    LeftNeutralSinceArm := FALSE;   // 🔧 2026-07-03terdecies — repart propre au prochain armement
    DeadmanTimer(IN := FALSE, PT := DeadmanRearmTimeout);   // 🆕 2026-07-03decies — pas d'accumulation à froid
    NeutralHoldTimer(IN := FALSE, PT := NeutralHoldTime);   // 🆕 2026-07-03duodecies — idem
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    LastMode := Mode;   // 🆕 REX 2026-07-08 — pas de faux changement détecté à la réactivation
    RETURN;
END_IF;

Ready := TRUE; Busy := TRUE;

// 🔑 2. RESET DÉFAUT (front uniquement + cause disparue, Partie3 §5)
// ⚠️ CORRECTIF (revue de code 2026-07-01) : l'ancienne version effaçait le défaut sur simple
// niveau `Reset AND Error`, sans front ET sans vérifier que la cause (calib hors plage) avait
// disparu — un Reset maintenu (bouton IHM bloqué) effaçait le défaut en boucle même si RawX/Y
// restaient hors plage. Non conforme au guardrail Reset (CLAUDE.md, Partie3 §5).
ResetEdge(CLK := Reset);
IF ResetEdge.Q AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📥 3. ACQUISITION TIMING & BOUTON
CycleTimeCalc();
Button := RawButton;

// 🎯 4. CALIBRATION DYNAMIQUE (Zone RETAIN)
IF Calibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;
        NeutralYMem := RawY;
    ELSE
        // 🔧 CORRECTIF N7 (revue de code) : un seul bit pour une seule cause (Partie3 §3),
        // l'ancienne valeur 16#0003 levait à tort les bits 0 ET 1 pour un même défaut.
        ErrorId := ErrorId OR 16#0001;
    END_IF;
END_IF;
Error := (ErrorId <> 16#0000);
LastCalibrate := Calibrate;

// 🧮 4bis. MISE À L'ÉCHELLE (avant homme-mort — le neutre s'évalue sur les 2 axes déjà deadbandés)
ScaleX(RawIn := RawX, Neutral := NeutralXMem, Deadband := Deadband);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, Deadband := Deadband);

// 🆕 4ter-bis. CHANGEMENT DE MODE (REX 2026-07-08, demande utilisateur) : désarme le homme-mort
// dès que Mode change (MAINT_N1/N2/SEMI_AUTO/AUTO) — évite qu'une commande en cours (manche non
// centré) ne "traverse" le changement de mode et ne soit réinterprétée soudainement dans le
// nouveau contexte de mode (risque de mouvement soudain). Repassage par le neutre + nouvel appui
// bouton exigé, comme n'importe quel désarmement (§4ter ci-dessous).
IF Mode <> LastMode THEN
    DeadmanArmed := FALSE;
    LeftNeutralSinceArm := FALSE;
END_IF;
LastMode := Mode;

// 🆕 4ter-ter. FIN DE CYCLE GRAPPIN (REX 2026-07-08, demande utilisateur) : désarme le homme-mort
// dès que Grappin.Busy retombe (cible atteinte ou retour position départ). Sans ça, si l'opérateur
// tient encore le manche poussé (ce qu'il fait pour piloter le grappin via M2), les gates
// "NOT Grappin.Busy" côté PRG_06_WinchControl s'ouvrent immédiatement pour M1 ET M2 — les deux
// treuils démarrent alors directement sur la commande manche en cours, sans repasser par le
// neutre, et FB_WinchSync (réactivé au même instant) détecte aussitôt un écart de position
// (M1 immobile pendant le cycle, M2 ayant bougé de l'offset grappin) → faux défaut synchro.
GrappinBusyFallEdge(CLK := GrappinBusy);
IF GrappinBusyFallEdge.Q THEN
    DeadmanArmed := FALSE;
    LeftNeutralSinceArm := FALSE;
END_IF;

// 🔴 4ter. BOUTON HOMME-MORT (2026-07-03octies + renforcé decies/duodecies/terdecies — voir en-tête)
DeadmanEdge(CLK := RawButton);

// 🔧 2026-07-03terdecies (CORRECTIF review) : `LeftNeutralSinceArm` distingue "vient d'armer,
// n'a pas encore bougé" (NE DOIT PAS désarmer, même après NeutralHoldTime — l'opérateur a le
// temps qu'il veut pour démarrer son geste après l'appui) de "a bougé, PUIS est revenu au
// neutre" (là, `NeutralHoldTime` s'applique normalement, voir plus bas). Sans ce garde-fou, un
// opérateur qui arme puis hésite plus de NeutralHoldTime avant de bouger se faisait désarmer
// silencieusement (fail-safe, mais contredisait l'intention D57).
IF NOT DeadmanArmed THEN
    LeftNeutralSinceArm := FALSE;   // Repos/désarmé : prêt pour le prochain armement
ELSIF NOT ((ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0)) THEN
    LeftNeutralSinceArm := TRUE;    // Armé et a quitté le neutre au moins une fois : geste réellement démarré
END_IF;

// Le neutre doit être TENU `NeutralHoldTime` avant de désarmer (pas juste traversé) — sinon une
// inversion de sens rapide (Fwd→Rev) désarmerait à tort au passage par le neutre. Ne s'applique
// QU'APRÈS un geste réellement démarré (`LeftNeutralSinceArm`), jamais juste après l'armement.
NeutralHoldTimer(IN := DeadmanArmed AND LeftNeutralSinceArm AND (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0),
                 PT := NeutralHoldTime);
IF NeutralHoldTimer.Q THEN
    DeadmanArmed := FALSE;      // Neutre tenu assez longtemps APRÈS un geste démarré = fin réelle
END_IF;
IF DeadmanEdge.Q AND (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0) THEN
    DeadmanArmed := TRUE;       // Appui bouton AU NEUTRE = armement
END_IF;

// 🆕 4quater. RECONFIRMATION PÉRIODIQUE (2026-07-03decies, CORRIGÉ undecies suite review) — tant
// qu'armé ET en mouvement (hors neutre), le bouton doit être soit MAINTENU, soit ré-appuyé, avant
// DeadmanRearmTimeout. ⚠️ CORRECTIF : le 1er jet ne détectait qu'un FRONT (`DeadmanEdge.Q`) — un
// opérateur qui MAINTIENT le bouton enfoncé en continu (réflexe naturel homme-mort) ne générait
// plus jamais de front après le 1er appui → désarmement surprise au bout de 3s MALGRÉ la présence
// continue. Corrigé : `NOT RawButton` (niveau, pas front) — maintenir OU réappuyer dans le délai
// remettent tous les deux `IN` à FALSE (TON.ET repart de 0), seul un RELÂCHEMENT PROLONGÉ désarme.
DeadmanTimer(IN := DeadmanArmed AND NOT ((ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0)) AND NOT RawButton,
             PT := DeadmanRearmTimeout);
IF DeadmanTimer.Q THEN
    DeadmanArmed := FALSE;      // Pas de reconfirmation dans le délai → désarmement (décélération sûre)
END_IF;

// 🕹️ 5. PIPELINE TRAITEMENT — AXE X
IF InvertX THEN
    FilterX(ValueIn := -ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterX(ValueIn := ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// 🔴 Cible rampe forcée à 0 tant que le geste n'est pas armé (homme-mort, voir §4ter)
RampX(Target := SEL(DeadmanArmed, 0.0, FilterX.ValueOut), AccelRate := AccelRate, DecelRate := DecelRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

// Mapping Sortie Standardisée Axe X
// 🔧 2026-07-02 : SpeedRef désormais SIGNÉ (plus de ABS) — le signe porte le sens, cohérent
// avec Direction ci-dessous (même seuil 0.1, même variable RampX.Current). StartStop reste
// calculé sur la MAGNITUDE (indépendant du signe) : sinon un mouvement négatif (< -0.1) serait
// à tort interprété comme "pas de mouvement" (StartStop=FALSE) par le test `> 0.1` direct.
AxisCmdX.Enable := TRUE;
AxisCmdX.SpeedRef := RampX.Current;
AxisCmdX.StartStop := (ABS(RampX.Current) > 0.1);

IF RampX.Current > 0.1 THEN     AxisCmdX.Direction := 1;
ELSIF RampX.Current < -0.1 THEN AxisCmdX.Direction := -1;
ELSE AxisCmdX.Direction := 0;   AxisCmdX.SpeedRef := 0.0;
END_IF;

// 🆕 Miroirs maintenance (voir en-tête) — mêmes valeurs, à plat
SpeedXPct := AxisCmdX.SpeedRef;
DirectionX := AxisCmdX.Direction;

// 🕹️ 6. PIPELINE TRAITEMENT — AXE Y (ScaleY déjà calculé en §4bis, avant homme-mort)
IF InvertY THEN
    FilterY(ValueIn := -ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterY(ValueIn := ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// 🔴 Cible rampe forcée à 0 tant que le geste n'est pas armé (homme-mort, voir §4ter)
RampY(Target := SEL(DeadmanArmed, 0.0, FilterY.ValueOut), AccelRate := AccelRate, DecelRate := DecelRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

// Mapping Sortie Standardisée Axe Y
// 🔧 2026-07-02 : voir note axe X ci-dessus (même principe, SpeedRef signé + StartStop sur magnitude)
AxisCmdY.Enable := TRUE;
AxisCmdY.SpeedRef := RampY.Current;
AxisCmdY.StartStop := (ABS(RampY.Current) > 0.1);

IF RampY.Current > 0.1 THEN     AxisCmdY.Direction := 1;
ELSIF RampY.Current < -0.1 THEN AxisCmdY.Direction := -1;
ELSE AxisCmdY.Direction := 0;   AxisCmdY.SpeedRef := 0.0;
END_IF;

// 🆕 Miroirs maintenance (voir en-tête) — mêmes valeurs, à plat
SpeedYPct := AxisCmdY.SpeedRef;
DirectionY := AxisCmdY.Direction;

// 📤 7. VALIDATION DES SORTIES ÉTAT
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
Done := NOT Error;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Modes) ===

// 🛑 1. GATE — repli sur le mode de sécurité de veille (DISABLE) si désactivé
// ou si l'arrêt d'urgence est déclenché.
IF NOT Enable OR NOT EmergencyStopOk THEN
    Mode := E_Mode.DISABLE;
    SyncEnable := TRUE;
    InhibitM1 := FALSE;
    InhibitM2 := FALSE;
    HomingApproachEnable := FALSE;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. GARDE-FOUS
// bit0 : SEMI_AUTO demandé mais défaut codeur présent → refusé, repli MAINT_N1
IF (ModeRequest = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📤 4. ARBITRAGE DU MODE
// 🔧 REX 2026-07-07 : plus de garde-fou mot de passe ici — MAINT_N2 accepté directement,
// l'accès est filtré en amont côté IHM (visibilité des actions selon niveau utilisateur).
IF (ModeRequest = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    Mode := E_Mode.MAINT_N1;
ELSE
    Mode := ModeRequest;
END_IF;

// 📤 5. SYNC ENABLE — actionnable en MAINT_N1 OU MAINT_N2 (Décision D_OVERRIDESYNC 2026-07-04)
// Anciennement restreint à MAINT_N2 uniquement, mais l'opérateur peut avoir besoin de la
// procédure de récupération mou câble dès MAINT_N1. 🔧 REX 2026-07-08 : polarité inversée —
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
SyncEnable := NOT ((Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) AND NOT SyncEnableRequest);

// 📤 5bis. INHIBITION TREUIL — mise en service, demande utilisateur (REX 2026-07-08)
// UNIQUEMENT actionnable en MAINT_N2 (contrairement à SyncEnable, actionnable aussi N1) —
// action plus sensible (neutralise complètement un treuil ET sa propre supervision safety),
// réservée au niveau de droits le plus élevé. Centralisé ICI (comme SyncEnable) : aucun
// autre fichier ne doit re-tester Mode=MAINT_N2 pour ce besoin.
InhibitM1 := (Mode = E_Mode.MAINT_N2) AND InhibitM1Request;
InhibitM2 := (Mode = E_Mode.MAINT_N2) AND InhibitM2Request;

// 📤 5ter. OVERRIDE ARRÊT HAUT — mise en service, demande utilisateur (REX 2026-07-08 (2))
// UNIQUEMENT actionnable en MAINT_N2 — remplace l'ancien test direct Mode<>MAINT_N2 dans
// PRG_06_WinchControl.st, qui bypassait l'arrêt normal pour N'IMPORTE QUELLE opération N2.
// Désormais un choix conscient explicite est requis EN PLUS du mode.
HomingApproachEnable := (Mode = E_Mode.MAINT_N2) AND HomingApproachEnableRequest;

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Output) ===

// 1. Inversion NO/NC
State := Command XOR InvertLogic;

// 2. Option blink 1 Hz (diagnostic/visualisation) — modulation à 500ms ON/500ms OFF
IF Blink1Hz AND State THEN
    BlinkTimer(IN := NOT BlinkTimer.Q, PT := T#500ms);
    IF BlinkTimer.Q THEN
        BlinkState := NOT BlinkState;
    END_IF;
    State := BlinkState;
ELSE
    BlinkTimer(IN := FALSE, PT := T#500ms);
    BlinkState := FALSE;
END_IF;

// 3. Double vérification commande/retour (contacteur collé/ne colle pas)
IF UseFeedback THEN
    FeedbackTon(IN := (State <> FeedbackRaw), PT := FeedbackTimeout);
    IF FeedbackTon.Q THEN
        ErrorId := ErrorId OR 16#0001;
        FeedbackOk := FALSE;
    ELSE
        ErrorId := ErrorId AND 16#FFFE;
        FeedbackOk := TRUE;
    END_IF;
ELSE
    FeedbackTon(IN := FALSE, PT := FeedbackTimeout);
    FeedbackOk := TRUE;   // Pas de contrôle demandé — pas d'incohérence à signaler
END_IF;

// 4. Diagnostic voie/carte
IF NOT ChannelOk THEN
    ErrorId := ErrorId OR 16#0002;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

Error := (ErrorId <> 16#0000);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Ramp) ===

// Détection du comportement (Accélération vs Décélération)
// 🔧 CORRECTIF : classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut
// de Target seul (l'ancienne version se trompait lors d'une traversée de zéro rapide).
IF (Current >= 0.0 AND Target >= Current) OR (Current <= 0.0 AND Target <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < Target THEN
    Current := Current + StepX;
    IF Current > Target THEN Current := Target; END_IF;
ELSIF Current > Target THEN
    Current := Current - StepX;
    IF Current < Target THEN Current := Target; END_IF;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Safety_Chariot) ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Ready := FALSE;
    SafeStop := TRUE;
    PowerCutOff := FALSE;
    State := E_State.DISABLED;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC DU DOMAINE CHARIOT
IF NOT JoystickOnline OR NOT JoystickOperational THEN
    ErrorId := ErrorId OR 16#0001;       // Perte joystick/CAN : pas de commande opérateur valide
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔴 TBD (EtherCAT AC600 non finalisé) : bit1 réservé perte EtherCAT variateur — NON câblé
// dans ce lot. Ne jamais mettre un stub qui masquerait un vrai défaut : laisser le bit à 0
// tant que la surveillance EtherCAT n'est pas fiabilisée revient à accepter ce risque, comme
// pour le codeur treuil (FB_Safety_Winch) — décision à revalider avec l'utilisateur avant
// mise en service réelle en mode ETHERCAT.

// 🔍 3bis. ROTATION DE PHASE (câblé — I/O réel, commun M1/M2/M3, 2026-07-03octodecies) — bit2
IF NOT PhaseRotationOk THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (REX 2026-07-08, demande utilisateur) — bit3
// Signal commun (1 seul fil, câblé identiquement sur les 3 instances Safety) : sa perte peut
// signifier qu'un frein colle instantanément (frein à manque de courant) → SafeStop (via Error)
// ET PowerCutOff (voir bandeau en-tête).
IF BrakeThermalFeedback THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SafeStop := Error OR NOT EmergencyStopOk;  // 🟧 Tout défaut du domaine ou contacteur coupé → SafeStop
// 🧨 REX 2026-07-08 : PowerCutOff devient réel pour bit3 (thermique frein commun) uniquement —
// même raisonnement que FB_Safety_Winch bit10 (voir bandeau en-tête). Les autres bits du domaine
// Chariot (joystick/CAN, rotation phase) restent TBD, pas de ST_ContactorCheck de puissance câblé.
PowerCutOff := (ErrorId AND 16#0008) <> 16#0000;

Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Safety_Winch) ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Ready := FALSE;
    SafeStop := TRUE;
    ForbidDescent := TRUE;
    PowerCutOff := FALSE;
    State := E_State.DISABLED;
    Error := FALSE;
    ErrorId := 16#0000;
    // 🔧 REX 2026-07-08 : force le réarmement (WasArmed→FALSE) via FB_DriftGuard, comportement
    // identique à l'ancien MecaA_Armed/MecaC_Armed := FALSE.
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := GrappinSlipToleranceM);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;
CycleTimeCalc(DefaultValueS := 0.010); // 🔧 REX 2026-07-07 — Méca A

// Détecte la fin du référencement pour éviter le pic de vitesse au cycle de transition (offset appliqué)
IF LastInReferencingMode AND NOT InReferencingMode THEN
    LastCablePosM := CablePosM;
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM); // 🔧 REX 2026-07-08
END_IF;
LastInReferencingMode := InReferencingMode;

// Si le contacteur de puissance est ouvert (EmergencyStopOk = FALSE), on force les sorties de sécurité
// mais on ne fait pas de RETURN pour permettre le diagnostic et l'acquittement (Reset) des défauts.
IF NOT EmergencyStopOk THEN
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM); // 🔧 REX 2026-07-08
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := GrappinSlipToleranceM);       // 🔧 REX 2026-07-08
    LastCablePosM := CablePosM;    // 🔧 REX 2026-07-07 (2) : évite le pic de vitesse au premier cycle actif
END_IF;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC DU DOMAINE TREUIL
IF NOT JoystickOnline OR NOT JoystickOperational THEN
    ErrorId := ErrorId OR 16#0001;       // Perte joystick/CAN : pas de commande opérateur valide
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 3bis. PERTE CODEUR DE CE TREUIL (câblé — lot Codeur 2026-07-02)
IF NOT EncoderAvailable THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🔍 3ter. SURCHAUFFE MOTEUR (câblé — I/O réel 2026-07-02) — bit2, participe au SafeStop total
IF ThermalFeedback THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// 🔍 3quater. MOU DE CÂBLE (physiquement sur tambour M2, câblé sur les 2 instances Safety)
// Mode NORMAL (SyncEnable=TRUE) → SafeStop M1+M2 (bit3 inclus dans SafeStop)
// Mode RÉCUPÉRATION (SyncEnable=FALSE) → ForbidAscent uniquement (montée interdite, descente OK)
IF SlackCableDetected THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q AND NOT SlackCableDetected THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🔍 3quinquies. ROTATION DE PHASE (câblé — I/O réel, commun M1/M2, 2026-07-03octodecies) —
// bit4, participe au SafeStop total (sens moteur potentiellement inversé, danger 2 sens).
IF NOT PhaseRotationOk THEN
    ErrorId := ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFEF;
END_IF;

// 🔍 3sexties. FIN DE COURSE HAUT / CAPTEUR DE POSITION HAUTE (anti-débordement) — bit5
// ⚠️ Convention NAMING_CONVENTION.md : TopPositionSensor TRUE = sain/non atteint (NF), FALSE =
// position haute réellement atteinte (contact ouvert). Si la position haute EST atteinte
// (TopPositionSensor=FALSE), qu'on n'est pas en phase de référencement (homing), ET qu'on
// commande un mouvement vers le haut (Direction > 0), alors on lève le défaut.
IF NOT TopPositionSensor AND NOT InReferencingMode AND (Direction > 0) THEN
    ErrorId := ErrorId OR 16#0020;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFDF;
END_IF;

// 🔍 3septies. LONGUEUR MAX DE CÂBLE (profondeur max autorisée) — bit6
// Sécurité active hors référencement. Si la position de câble descend sous la limite basse physique (CablePosM <= CableLimitDescentM),
// alors on interdit uniquement la descente.
IF (CableLimitDescentM < 0.0) AND (CablePosM <= CableLimitDescentM) AND NOT InReferencingMode THEN
    ErrorId := ErrorId OR 16#0040;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFBF;
END_IF;

// 🔍 3octies. MÉCA A — MOUVEMENT NON COMMANDÉ GÉNÉRAL (REX 2026-07-07) — bit7
// Armé quand tout est physiquement confirmé coupé (contacteurs + frein). Si dérive ou vitesse
// détectée pendant que c'est armé → roue libre / frein insuffisant.
// 🔧 REX 2026-07-08 : dérive factorisée via FB_DriftGuard (CODE/WINCH/) — comportement inchangé,
// seul le check vitesse (MeasuredSpeedMps) reste géré ici (hors périmètre de la brique).
MeasuredSpeedMps := ABS(CablePosM - LastCablePosM) / CycleTimeCalc.CycleTimeS;
LastCablePosM := CablePosM;

DriftGuardA(
    Arm        := FwdRevSpeedFeedbackOff AND BrakeFeedback AND NOT InReferencingMode,
    PositionM  := CablePosM,
    ToleranceM := UncommandedDriftToleranceM
);
MecaADriftM := DriftGuardA.DriftM;   // 🆕 REX 2026-07-08 : diagnostic IHM

IF DriftGuardA.Violation OR (FwdRevSpeedFeedbackOff AND BrakeFeedback AND NOT InReferencingMode AND (MeasuredSpeedMps > UncommandedSpeedThresholdMps)) THEN
    ErrorId := ErrorId OR 16#0080;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FF7F;
END_IF;

// 🔍 3nonies. MÉCA B — PILOTAGE ACTIF SANS COMMANDE OPÉRATEUR (REX 2026-07-07) — bit8
// Indépendant de FB_Winch (défense en profondeur). Perte CAN (bit0) OU joystick au neutre ;
// si les contacteurs OU LE FREIN ne confirment pas être retombés/serrés dans PostRampTimeout, défaut.
// 🔧 REX 2026-07-08 (demande utilisateur) : BrakeFeedback ajouté — un frein qui ne confirme pas
// son engagement dans ce délai est tout aussi dangereux qu'un contacteur qui ne retombe pas
// (risque de mouvement/roue libre non détecté). Auparavant seul FwdRevSpeedFeedbackOff était vérifié.
MecaB_NoOperatorCmd := (NOT JoystickOnline) OR (NOT JoystickOperational) OR JoystickYNeutral;
TonMecaB(IN := MecaB_NoOperatorCmd AND NOT (FwdRevSpeedFeedbackOff AND BrakeFeedback), PT := PostRampTimeout);
MecaBElapsedTime := TonMecaB.ET;   // 🆕 REX 2026-07-08 : diagnostic IHM
IF TonMecaB.Q THEN
    ErrorId := ErrorId OR 16#0100;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FEFF;
END_IF;

// 🔍 3decies. MÉCA C — GLISSEMENT M1 PENDANT GRAPPIN, ESCALADE (REX 2026-07-07) — bit9
// Armé UNIQUEMENT pour l'instance M1 (GrappinHoldStillActive câblé sur instGrappin.Busy côté M1
// seulement, toujours FALSE côté M2). Tolérance plus large que celle de FB_Grappin (1.0 m) —
// n'intervient que si la couche Grappin (SafeStop M1 seul) n'a pas suffi.
// 🔧 REX 2026-07-08 : dérive factorisée via FB_DriftGuard (CODE/WINCH/) — comportement inchangé.
DriftGuardC(
    Arm        := GrappinHoldStillActive,
    PositionM  := CablePosM,
    ToleranceM := GrappinSlipToleranceM
);
MecaCDriftM := DriftGuardC.DriftM;   // 🆕 REX 2026-07-08 : diagnostic IHM

IF DriftGuardC.Violation THEN
    ErrorId := ErrorId OR 16#0200;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FDFF;
END_IF;

// 🔍 3undecies. THERMIQUE FREIN COMMUN M1/M2/M3 (REX 2026-07-08, demande utilisateur) — bit10
// Signal commun (1 seul fil, câblé identiquement sur les 3 instances Safety) : sa perte peut
// signifier qu'un frein colle instantanément (frein à manque de courant) → SafeStop ET
// PowerCutOff (voir bandeau en-tête).
IF BrakeThermalFeedback THEN
    ErrorId := ErrorId OR 16#0400;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FBFF;
END_IF;

// 🔍 3duodecies. MÉCA D — ARRIVÉE CAPTEUR HAUT HORS RÉFÉRENCEMENT (REX 2026-07-08 (3),
// demande utilisateur) — bit11
// Complète le bit5 (ForbidAscent immédiat) : arme la MÊME condition (capteur haut atteint, hors
// homing) mais avec un délai de confirmation, comme Méca B. Si les contacteurs ET le frein ne
// confirment pas être retombés/serrés dans PostRampTimeout après l'arrivée au capteur → défaut
// → SafeStop ET PowerCutOff (la coupure ForbidAscent seule n'a visiblement pas suffi à arrêter
// réellement le treuil : roue libre ou contacteur/frein défaillant).
TonMecaD(
    IN := (((NOT TopPositionSensor AND NOT InReferencingMode) 
            OR (Homed AND NOT HomingSuspect AND (CablePosM >= (TopLimitM + 0.10))))
           AND (Direction >= 0)) // 🆕 Neutralise la butée haute en descente (Direction = -1)
          AND NOT (FwdRevSpeedFeedbackOff AND BrakeFeedback), 
    PT := PostRampTimeout
);
IF TonMecaD.Q THEN
    ErrorId := ErrorId OR 16#0800;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#F7FF;
END_IF;

// 🔍 3terdecies. MÉCA E — ÉCART SYNCHRO M1/M2 CRITIQUE (REX 2026-07-08 (4)) — bits 12/13
// Couche INDÉPENDANTE de FB_WinchSync (écart mineur, 1er niveau) — défense en profondeur pour un
// écart VRAIMENT important. ExpectedOtherWinchPosM est DÉJÀ corrigé de l'offset grappin actif par
// l'appelant : comparaison directe valable que le grappin soit ouvert, fermé, ou absent du calcul.
// Suppression pendant GrappinBusy (trajet actif = écart transitoire normal, pas un défaut),
// InReferencingMode (position pas fiable pendant homing) et OtherWinchInhibited (🆕 REX
// 2026-07-08 (7) : l'autre treuil en maintenance a une position figée, non comparable).
// Bit12 : détection → SafeStop immédiat. Bit13 : escalade si pas confirmé arrêté → PowerCutOff.
IF SyncEnable AND NOT GrappinBusy AND NOT InReferencingMode AND NOT OtherWinchInhibited
   AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
    ErrorId := ErrorId OR 16#1000;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#EFFF;
END_IF;

TonMecaE(IN := ((ErrorId AND 16#1000) <> 16#0000) AND NOT (FwdRevSpeedFeedbackOff AND BrakeFeedback),
         PT := PostRampTimeout);
IF TonMecaE.Q THEN
    ErrorId := ErrorId OR 16#2000;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#DFFF;
END_IF;

// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);       // 🧭 Partie3 §4 : miroir de TOUT le domaine, y compris mou de câble (visible IHM)
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🟧 SafeStop : bits 0/1/2/3/4 (joystick, codeur, thermique moteur, MOU CÂBLE, phases) + 7/8/9
// (Méca A/B/C) + 10 (thermique frein commun) + 11 (Méca D) + 12/13 (🆕 REX 2026-07-08 (4) :
// Méca E, écart synchro critique) ou si contacteur coupé
IF NOT EmergencyStopOk THEN
    SafeStop := TRUE;
ELSIF NOT SyncEnable THEN
    SafeStop := (ErrorId AND 16#3F97) <> 16#0000;   // bit3 exclu → SafeStop normal sans mou câble
ELSE
    SafeStop := (ErrorId AND 16#3F9F) <> 16#0000;   // bit3 inclus → SafeStop complet avec mou câble
END_IF;

// ⬇️ ForbidDescent : bit6 uniquement (limite basse câble) ou si contacteur coupé
ForbidDescent := (ErrorId AND 16#0040) <> 16#0000 OR NOT EmergencyStopOk;

// ⬆️ ForbidAscent : bit5 (fin course haut) OU bit3+(NOT SyncEnable) (récupération mou câble : montée interdite même en récup)
// 🆕 REX 2026-07-08 : Sécurité positive maintenue si capteur haut physiquement activé hors référencement,
// même si l'alarme IHM (bit5) a été acquittée pour permettre la descente.
ForbidAscent := (ErrorId AND 16#0020) <> 16#0000
             OR (NOT TopPositionSensor AND NOT InReferencingMode)
             OR ((ErrorId AND 16#0008) <> 16#0000 AND NOT SyncEnable);

// 🧨 REX 2026-07-07 : PowerCutOff enfin réel — bits 7/8/9 (Méca A/B/C, voir bandeau en-tête).
// Coupure puissance amont : les contacteurs locaux sont déjà confirmés coupés/insuffisants,
// SafeStop seul ne sert à rien dans ces 3 cas précis.
// 🆕 REX 2026-07-08 (demande utilisateur) : bit2 (surchauffe/perte thermique MOTEUR) et bit10
// (surchauffe/perte thermique FREIN commun) ajoutés — un frein à manque de courant peut coller
// instantanément sur perte de son retour thermique : une rampe SafeStop seule ne protège pas la
// mécanique dans ce cas, coupure puissance immédiate nécessaire. Même raisonnement appliqué au
// thermique moteur par cohérence/défense en profondeur (demande explicite).
// 🆕 REX 2026-07-08 (3) : bit11 (Méca D, capteur haut) ajouté — même raisonnement que Méca A/B :
// contacteurs/frein déjà censés être coupés (ForbidAscent immédiat sur capteur), une confirmation
// manquante après délai signifie que la coupure locale n'a pas suffi.
// 🆕 REX 2026-07-08 (4) : bit13 (Méca E escalade) ajouté — PAS bit12 seul (détection immédiate =
// SafeStop uniquement ; PowerCutOff seulement si l'arrêt n'est pas confirmé après délai).
PowerCutOff := (ErrorId AND 16#2F84) <> 16#0000;

// Busy, Done non utilisés mais présents pour conformité (comme FB_DiagCanOpen)
Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Chariot) ===

IF NOT Enable THEN
    ElapsedS := 0.0;
    LastTargetNum := TargetNum;
    PosFosse1 := FALSE; PosFosse2 := FALSE; PosMaintenance := FALSE; PosTremie := FALSE;
    RETURN;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);

// 🔁 Changement de cible = nouveau trajet, on repart de zéro
TargetChanged := (TargetNum <> LastTargetNum);
LastTargetNum := TargetNum;
IF TargetChanged THEN
    ElapsedS := 0.0;
END_IF;

// ⏱️ Progression du trajet UNIQUEMENT si un relais de sens est actif (mouvement réel demandé) ;
// à l'arrêt, la progression reste EN PAUSE (pas remise à zéro).
IF (RelayFwd OR RelayRev) AND (ElapsedS < TravelTimeS) THEN
    ElapsedS := ElapsedS + CycleTimeCalc.CycleTimeS;
    IF ElapsedS > TravelTimeS THEN
        ElapsedS := TravelTimeS;
    END_IF;
END_IF;

Reached := (ElapsedS >= TravelTimeS);

PosFosse1      := Reached AND (TargetNum = 1);
PosFosse2      := Reached AND (TargetNum = 2);
PosMaintenance := Reached AND (TargetNum = 3);
PosTremie      := Reached AND (TargetNum = 4);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_DigitalMirror) ===

IF NOT Enable THEN
    TonMirror(IN := FALSE, PT := MirrorDelay);
    Feedback := Command;   // Hors simulation : miroir idéal (comportement précédent conservé)
    RETURN;
END_IF;

TonMirror(IN := (Command <> Feedback), PT := MirrorDelay);
IF TonMirror.Q THEN
    Feedback := Command;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;

// 🆕 REX 2026-07-08 (4) — injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;

Increment := REAL_TO_UDINT(SpeedRefPct * 0.1 * SpeedScaleFactor);

IF PresetCmd THEN
    RawPos := PresetValue;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;

RawPosOut := RawPos;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

// 🔑 Initialise au neutre au premier cycle uniquement — ensuite RawX/RawY/RawButton
// restent forçables librement en instance CODESYS (un Force n'est jamais écrasé par TRUE,
// mais une simple écriture cyclique l'écraserait — donc pas de ré-assignation continue ici).
IF NOT Enable THEN
    FirstCycle := TRUE;
    RETURN;
END_IF;

IF FirstCycle THEN
    RawX := NeutralRaw;
    RawY := NeutralRaw;
    RawButton := FALSE;
    FirstCycle := FALSE;
END_IF;

// === IMPLEMENTATION ===
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    ContactorLatch := FALSE;
    RETURN;
END_IF;

// 1. La chaîne AU est saine si le PLC maintient les deux relais de coupure de puissance
// (on simule que les boutons AU physiques coup-de-poing sont toujours au repos/relâchés)
SimChainOk := PowerCutOff_A AND PowerCutOff_B;

// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure
IF NOT SimChainOk THEN
    ContactorLatch := FALSE;
ELSIF EmergencyArming THEN
    ContactorLatch := TRUE;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_SpeedStep) ===

// 🛑 1. GATE — pas de mouvement demandé = palier 0, tous contacteurs à FALSE
IF NOT Enable THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
    RETURN;
END_IF;

// 🪜 2. SÉLECTION DU PALIER (HYSTERESIS lib Util : IN/HIGH/LOW → OUT)
//    OUT = TRUE tant que IN < LOW (régime "bas") ; OUT bascule à FALSE une fois
//    IN > HIGH (régime "haut" confirmé) ; maintien entre LOW et HIGH (anti-battement).
//    => NOT Hyst_n.OUT = "on a franchi le seuil n vers le haut" (palier n+1 atteint).
SpeedRefInt := REAL_TO_INT(SpeedRefPct);

Hyst1(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[1] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[1] - HystMargin));
Hyst2(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[2] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[2] - HystMargin));
Hyst3(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[3] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[3] - HystMargin));
Hyst4(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[4] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[4] - HystMargin));

StepNumber := 1;                          // Palier mini dès qu'Enable est actif
IF NOT Hyst1.OUT THEN StepNumber := 2; END_IF;
IF NOT Hyst2.OUT THEN StepNumber := 3; END_IF;
IF NOT Hyst3.OUT THEN StepNumber := 4; END_IF;
IF NOT Hyst4.OUT THEN StepNumber := 5; END_IF;

// 🆕 2bis. PLAFOND (2026-07-03quinquies) — appliqué APRÈS la sélection hystérésis,
// AVANT la lecture table : le 0..100% de la consigne peut réclamer le palier 5,
// mais ne dépassera jamais MaxStepNumber (ex. limitation couple en descente, voir FB_Winch)
IF StepNumber > MaxStepNumber THEN
    StepNumber := MaxStepNumber;
END_IF;

// 📤 3. CONTACTEURS — lus dans la table (donnée, jamais codé en dur)
CASE StepNumber OF
    1: Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2: Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3: Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4: Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5: Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
END_CASE;

IF NOT Enable OR NOT EmergencyStopOk THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    SpeedStep(Enable := FALSE, SpeedRefPct := 0.0, Table := SpeedStepTable, HystMargin := SpeedStepHystMargin);
    StepNumber := SpeedStep.StepNumber;
    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeCmd := Brake.BrakeCmd;
    BrakeContactorCheck := Brake.ContactorCheck;
    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := RampAccelRate, DecelRate := RampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);

ResetEdge(CLK := Reset);

DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

// 🆕 Mou de câble (ForbidDescent) et Fin de course haut (ForbidAscent) intégrés à une VRAIE
// décélération rapide (comme SafeStop) :
// - ForbidDescent est INHIBÉ si CommandedDirection = 1 (montée libre pour reprendre le mou)
// - ForbidAscent est INHIBÉ si CommandedDirection = -1 (descente libre pour dégager le câble)
EffectiveSafeStop := SafeStop 
                     OR (ForbidDescent AND (CommandedDirection <> 1))
                     OR (ForbidAscent AND (CommandedDirection <> -1));

RampTargetPct := 0.0;
IF NOT EffectiveSafeStop AND StartStop AND NOT DirectionChangePending THEN
    RampTargetPct := ABS(SpeedRefPct);

    // 🆕 RALENTISSEMENT AUTOMATIQUE SUR BORDURES (si référencé et non suspect)
    // Permet d'approcher les fins de course / limites en vitesse lente de façon progressive
    IF Homed AND NOT HomingSuspect THEN
        // En montée (engagement ou mouvement actif), ralentit à l'approche de la limite haute
        IF ((CommandedDirection = 1) OR (Direction = 1)) AND (CablePosM >= (TopLimitM - SlowdownDistanceM)) THEN
            RampTargetPct := MIN(RampTargetPct, SlowSpeedPct);
        END_IF;

        // En descente (engagement ou mouvement actif), ralentit à l'approche de la limite basse
        IF ((CommandedDirection = -1) OR (Direction = -1)) AND (CablePosM <= (BottomLimitM + SlowdownDistanceM)) THEN
            RampTargetPct := MIN(RampTargetPct, SlowSpeedPct);
        END_IF;
    END_IF;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := RampAccelRate,
          DecelRate := SEL(EffectiveSafeStop, RampDecelNormalRate, RampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

// 🆕 Plafond dynamique de palier (MaxStepDescente en descente, Palier 1 si non référencé ou douteux, Palier 1 en approche homing)
IF NOT Homed OR HomingSuspect THEN
    ActiveMaxStep := 1;
ELSIF CommandedDirection = -1 THEN
    ActiveMaxStep := MaxStepDescente;
ELSIF (CommandedDirection = 1) AND HomingApproachActive THEN
    ActiveMaxStep := 1;
ELSE
    ActiveMaxStep := 5;
END_IF;

SpeedStep(Enable := (ABS(SpeedRamp.Current) > 0.1), SpeedRefPct := ABS(SpeedRamp.Current),
          Table := SpeedStepTable, HystMargin := SpeedStepHystMargin,
          MaxStepNumber := ActiveMaxStep);
StepNumber := SpeedStep.StepNumber;
Contactor1 := SpeedStep.Contactor1;
Contactor2 := SpeedStep.Contactor2;
Contactor3 := SpeedStep.Contactor3;
Contactor4 := SpeedStep.Contactor4;

RelayFwd := (CommandedDirection = 1) AND (StepNumber > 0);
RelayRev := (CommandedDirection = -1) AND (StepNumber > 0);

IF ForbidDescent THEN
    RelayRev := FALSE;
END_IF;

IF ForbidAscent THEN
    RelayFwd := FALSE;
END_IF;

Brake(Enable := TRUE, Reset := Reset, MovementRequested := (RelayFwd OR RelayRev),
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeCmd := Brake.BrakeCmd;
BrakeContactorCheck := Brake.ContactorCheck;

// 🔧 REX 2026-07-07 : vérification UNIQUEMENT à l'arrêt commandé (plus de détail par sens —
// voir bandeau en-tête). AllContactorsCommandedOff = tout ce que FB_Winch commande est à FALSE.
AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;   // TRUE = au moins un contacteur commandé
ContactorsCheck.Feedback := NOT FwdRevSpeedFeedbackOff;      // TRUE = au moins un contacteur pas retombé
TonContactorsDropped(IN := AllContactorsCommandedOff AND NOT FwdRevSpeedFeedbackOff, PT := ContactorFeedbackTimeout);
IF TonContactorsDropped.Q THEN
    ContactorsCheck.StuckClosed := TRUE;
ELSIF ResetEdge.Q THEN
    ContactorsCheck.StuckClosed := FALSE;
END_IF;
ContactorsCheck.StuckOpen := FALSE; // Non applicable avec ce retour (pas de confirmation par sens, voir bandeau)

IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🧪 Simulation (GVL_Simulation.ContactorFeedbackMx_IsReal, passé par l'appelant via
// BypassContactorCheck) — sans contacteurs réels câblés/cohérents en essai, StuckClosed
// se déclenche à tort et bloque RelayFwd/RelayRev (voir Error plus bas).
// 🔧 REX 2026-07-07 : bit2 (ex-RevContactorCheck) libre/inutilisé, fusionné dans bit1.
IF NOT BypassContactorCheck THEN
    IF ContactorsCheck.StuckClosed THEN
        ErrorId := ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
ELSE
    ErrorId := ErrorId AND 16#FFFD;   // Bypass actif : efface/maintient à 0 le bit1
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

IF (NOT StartStop OR EffectiveSafeStop OR DirectionChangePending) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

IF Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_WinchSync) ===

// 🛑 1. GATE
IF NOT Enable OR NOT EmergencyStopOk THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    DeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9, décisions actées 2026-07-02)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // 🔧 REX 2026-07-08 : ex-NOT OverrideSync, polarité déjà positive
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : pas de logique dédiée (FB_Cycle absent), actif par prudence
END_CASE;

// 📏 4. ÉCART M1/M2 — fiable UNIQUEMENT si les 2 treuils sont homés
IF HomedM1 AND HomedM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;

// 🔍 5. DÉTECTION ÉCART HORS TOLÉRANCE — bit0
// 🔧 REX 2026-07-08 (5) : filtre temporel (même pattern que MismatchTimer bit1) — absorbe le
// transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2), évite le blocage
// intempestif constaté sur incident terrain (0.24m transitoire).
DeviationActive := SyncActive AND HomedM1 AND HomedM2 AND (DeltaPosM > SyncToleranceM);
DeviationTimer(IN := DeviationActive, PT := T#800ms);  // 🔧 théorique, à ajuster sur site — absorbe le transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2)
IF DeviationTimer.Q THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT DeviationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 5bis. COHÉRENCE DES COMMANDES SÉCURITÉ — bit1
// Vérifie que les commandes envoyées aux deux treuils sont identiques (sens et contacteurs)
// Filtre de 500ms pour tolérer les transitions et rampes.
MismatchActive := SyncActive AND (
    (RelayFwdM1 <> RelayFwdM2) OR
    (RelayRevM1 <> RelayRevM2) OR
    (Contactor1_M1 <> Contactor1_M2) OR
    (Contactor2_M1 <> Contactor2_M2) OR
    (Contactor3_M1 <> Contactor3_M2) OR
    (Contactor4_M1 <> Contactor4_M2)
);

MismatchTimer(IN := MismatchActive, PT := T#500ms);

IF MismatchTimer.Q THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SyncWarn := Error;   // ⚠️ IHM uniquement — voir en-tête, pas de SafeStop
Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (corps du PROGRAM PRG_00_Inputs) ===

// 🛑 ─── COMMUN ────────────────────────────────────────────────────────────
// 🧪 Simulation : chaque OR ci-dessous force le capteur à son état "sain" (famille
// sécurité, TRUE=OK) quand SimulationModeActive ET que ce capteur précis n'est
// pas encore câblé réellement (GVL_Simulation.*_IsReal). Voir AF_Partie13.

// Simulation de la chaîne de sécurité AU / réarmement (Lot 1)
instSimSafety(
    Enable          := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EmergencyStopChain_IsReal,
    PowerCutOff_A   := PowerCutOff_A_RQ,
    PowerCutOff_B   := PowerCutOff_B_RQ,
    EmergencyArming := EmergencyArming_RQ
);

instEmergencyStopOk(InputRaw := EmergencyStopOk_DI OR instSimSafety.SimContactorOk, FilterTime := T#20MS);
EmergencyStopOk := instEmergencyStopOk.State;

// 🔧 REX 2026-07-07 : boucle AU (coup-de-poing + contact PLC) — distincte du contacteur de
// puissance ci-dessus. Réutilise le même flag simulation (même sous-système physique AU).
instEmergencyChain(InputRaw := EmergencyChainOK_DI OR instSimSafety.SimChainOk, FilterTime := T#20MS);
EmergencyChain := instEmergencyChain.State;

// 🔧 REX 2026-07-07 : M1_M2_SlackCableSwitch_DI → M2_SlackCableSwitch_DI (capteur physiquement
// uniquement sur le tambour M2, le préfixe M1_M2_ ne reflétait pas la réalité du câblage)
instSlackCableSwitch(InputRaw := M2_SlackCableSwitch_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SlackCableSwitch_IsReal), FilterTime := T#20MS);
SlackCableSwitch := instSlackCableSwitch.State;

// 🆕 REX 2026-07-08 (4) : cohérence simulation (demande utilisateur) — l'ancien câblage forçait
// TopPositionSensor à TOUJOURS TRUE (sain) en simulation, quelle que soit la position codeur :
// impossible de tester bit5/Méca D (capteur haut) en simulation, il ne se déclenchait JAMAIS.
// Dérivé désormais de la position M1 simulée (référence de l'ensemble, voir FB_Grappin/
// ActiveOffsetM) — 1 cycle de retard (PRG_00 avant PRG_02 dans l'ordre de tâche), négligeable,
// même principe déjà assumé ailleurs (EncoderFaultPresent, GrappinHoldStillActive).
SimTopSensorTriggered := (NOT PRG_04_Modes.instModes.InhibitM1 AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM >= GVL_PERSISTENT.HomingTargetM1_M))
                      OR (NOT PRG_04_Modes.instModes.InhibitM2 AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM >= GVL_PERSISTENT.HomingTargetM2_M));
instTopPositionSensor(InputRaw := M1_M2_TopPositionSensor_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.TopPositionSensor_IsReal AND NOT SimTopSensorTriggered), FilterTime := T#20MS);
TopPositionSensor := instTopPositionSensor.State;

instCtrlPhaseRotation(InputRaw := CtrlPhaseRotation_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.PhaseRotationOk_IsReal), FilterTime := T#20MS);
PhaseRotationOk := instCtrlPhaseRotation.State;

// 🆕 REX 2026-07-08 : thermique frein commun M1/M2/M3 (1 seul fil, voir bandeau ci-dessus)
instBrakeThermalFeedback(InputRaw := BrakeThermalFeedback_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BrakeThermal_IsReal), FilterTime := T#20MS);
BrakeThermalFeedback := instBrakeThermalFeedback.State;

// 🪝 ─── WINCH M1 ──────────────────────────────────────────────────────────
// 🧪 Simulation des retours contacteurs M1 (retombés si aucun sens/vitesse commandé)
M1_FwdRevSpeedFeedbackOff_Simulated := NOT (PRG_10_Outputs.M1RelayFwd OR PRG_10_Outputs.M1RelayRev OR PRG_10_Outputs.M1SpeedContactor1 OR PRG_10_Outputs.M1SpeedContactor2 OR PRG_10_Outputs.M1SpeedContactor3 OR PRG_10_Outputs.M1SpeedContactor4);
instM1FwdRevSpeedFeedbackOff(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM1_IsReal, M1_FwdRevSpeedFeedbackOff_DI, M1_FwdRevSpeedFeedbackOff_Simulated), FilterTime := T#20MS);
M1FwdRevSpeedFeedbackOff := instM1FwdRevSpeedFeedbackOff.State;

instM1Thermal(InputRaw := M1_ThermalFeedback_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ThermalM1_IsReal), FilterTime := T#20MS);
M1ThermalFeedback := instM1Thermal.State;

// 🧪 Simulation du retour frein M1 (fermé si commande inactive)
M1BrakeFeedback_Simulated := NOT PRG_10_Outputs.M1BrakeCmd;
instM1BrakeFeedback(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM1_IsReal, M1_BrakeFeedback_DI, M1BrakeFeedback_Simulated), FilterTime := T#20MS);
M1BrakeFeedback := instM1BrakeFeedback.State;

// 🪝 ─── WINCH M2 ──────────────────────────────────────────────────────────
// 🧪 Simulation des retours contacteurs M2 (retombés si aucun sens/vitesse commandé)
M2_FwdRevSpeedFeedbackOff_Simulated := NOT (PRG_10_Outputs.M2RelayFwd OR PRG_10_Outputs.M2RelayRev OR PRG_10_Outputs.M2SpeedContactor1 OR PRG_10_Outputs.M2SpeedContactor2 OR PRG_10_Outputs.M2SpeedContactor3 OR PRG_10_Outputs.M2SpeedContactor4);
instM2FwdRevSpeedFeedbackOff(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM2_IsReal, M2_FwdRevSpeedFeedbackOff_DI, M2_FwdRevSpeedFeedbackOff_Simulated), FilterTime := T#20MS);
M2FwdRevSpeedFeedbackOff := instM2FwdRevSpeedFeedbackOff.State;

instM2Thermal(InputRaw := M2_ThermalFeedback_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ThermalM2_IsReal), FilterTime := T#20MS);
M2ThermalFeedback := instM2Thermal.State;

// 🧪 Simulation du retour frein M2 (fermé si commande inactive)
M2BrakeFeedback_Simulated := NOT PRG_10_Outputs.M2BrakeCmd;
instM2BrakeFeedback(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM2_IsReal, M2_BrakeFeedback_DI, M2BrakeFeedback_Simulated), FilterTime := T#20MS);
M2BrakeFeedback := instM2BrakeFeedback.State;

// ↔️ ─── CHARIOT M3 ────────────────────────────────────────────────────────
// 🧪 Simulation dynamique du trajet M3 (FB_Sim_Chariot, non prioritaire — voir AF_Partie13
// §Chariot). Appelée AVANT les FB_Input pour que ses sorties soient à jour au même cycle
// (sinon décalage d'1 cycle sur le OR ci-dessous). Remplace le forçage manuel en vue instance.
instSimChariot(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ChariotPosition_IsReal,
    TargetNum   := GVL_Chariot_M3_Stub.StubChariotPositionSelect_IHM,
    RelayFwd    := GVL_Chariot_M3_Stub.M3_RelayFwd,
    RelayRev    := GVL_Chariot_M3_Stub.M3_RelayRev,
    TravelTimeS := 8.0
);

instChariotPosFosse1(InputRaw := PosFosse1_DI OR instSimChariot.PosFosse1, FilterTime := T#20MS);
ChariotPosFosse1 := instChariotPosFosse1.State;

instChariotPosFosse2(InputRaw := PosFosse2_DI OR instSimChariot.PosFosse2, FilterTime := T#20MS);
ChariotPosFosse2 := instChariotPosFosse2.State;

instChariotPosMaintenance(InputRaw := PosMaintenance_DI OR instSimChariot.PosMaintenance, FilterTime := T#20MS);
ChariotPosMaintenance := instChariotPosMaintenance.State;

instChariotPosTremie(InputRaw := PosTremie_DI OR instSimChariot.PosTremie, FilterTime := T#20MS);
ChariotPosTremie := instChariotPosTremie.State;

instM3BrakeFeedback(InputRaw := M3_BrakeFeedback_DI, FilterTime := T#20MS);
M3BrakeFeedback := instM3BrakeFeedback.State;

// === IMPLEMENTATION (corps du PROGRAM PRG_01_Diagnostics) ===

// 🧪 0. Simulation Joystick (Lot 3, priorité — voir CODE/SIMULATION/FB_Sim_Joystick.st) : appelée
// AVANT FB_Joystick_0 pour que ses sorties soient à jour au même cycle. Remplace l'ancien bypass
// homme-mort codé en dur dans FB_Joystick (GVL_DEBUG.DBG_DeadmanBypass_TEST) : quand
// NOT JoystickSignal_IsReal, ses sorties remplacent les entrées brutes ci-dessous ; le homme-mort
// réel de FB_Joystick n'est plus jamais contourné.
// 🆕 REX 2026-07-08 : gardé désormais par JoystickSignal_IsReal (PAS Joystick_IsReal, qui ne
// couvre que le bus CANopen ci-dessous) — granularité séparée demandée par l'utilisateur : tester
// le signal joystick réel sans dépendre du diagnostic bus/nœud CANopen (encore simulé sain).
instSimJoystick(
    Enable          := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.JoystickSignal_IsReal,
    NeutralRaw      := GVL_Simulation.JoystickForceNeutralRaw,
    MaxRaw          := GVL_Simulation.JoystickForceMaxRaw
);

// 1. Diagnostics CANopen — 🆕 REX 2026-07-08 : gardé par Joystick_IsReal UNIQUEMENT (bus/nœud),
// indépendant de JoystickSignal_IsReal (signal brut ci-dessus) — granularité séparée.
instDiagCanOpen(
    Enable := TRUE,
    Reset := PRG_09_Supervision.FaultMachineReset_IHM,
    CanOnline := (CANbus.GetBusState() = 1) OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.Joystick_IsReal), // 1 = ACTIVE (ou simulation)
    CanOperational := (JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState() = DEVICE_STATE.RUNNING) OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.Joystick_IsReal)
);

// 2. Diagnostics EtherCAT (variateur + 2 codeurs)
instDiagEthercat(
    Enable := TRUE,
    Reset := PRG_09_Supervision.FaultMachineReset_IHM,          // 🔑 Bouton général machine
    VariateurWcState := (AC600_ECAT_Drive.GetDeviceState() <> DEVICE_STATE.RUNNING) AND NOT (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.VariateurM3_IsReal),
    VariateurSlaveState := SEL((GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.VariateurM3_IsReal) OR (AC600_ECAT_Drive.GetDeviceState() = DEVICE_STATE.RUNNING), 0, 8),
    EncoderM1WcState := (COD1_CODEUR.GetDeviceState() <> DEVICE_STATE.RUNNING) AND NOT (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM1_IsReal),
    EncoderM1SlaveState := SEL((GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM1_IsReal) OR (COD1_CODEUR.GetDeviceState() = DEVICE_STATE.RUNNING), 0, 8),
    EncoderM2WcState := (COD2_CODEUR.GetDeviceState() <> DEVICE_STATE.RUNNING) AND NOT (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM2_IsReal),
    EncoderM2SlaveState := SEL((GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM2_IsReal) OR (COD2_CODEUR.GetDeviceState() = DEVICE_STATE.RUNNING), 0, 8)
);

// 3. Acquisition Joystick — RawX/RawY/RawButton simulés (instSimJoystick) quand NOT JoystickSignal_IsReal
// 🔴🔧 REX 2026-07-07 — TEST BANC UNIQUEMENT, PAS DE VALEUR PRODUCTION :
//    DeadmanRearmTimeout 10s → 5min, NeutralHoldTime 500ms → 1s (confort d'essai, moins de
//    réappuis/traversées à gérer). ⚠️ RÉDUIT RÉELLEMENT LA SÉCURITÉ HOMME-MORT — à repasser
//    impérativement à T#10S / T#500MS (ou retirer ces 2 lignes, le FB reprend ses défauts sûrs)
//    avant toute mise en service réelle avec la machine.
FB_Joystick_0(
    Enable              := TRUE,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    Mode                := PRG_04_Modes.instModes.Mode,  // 🆕 REX 2026-07-08 : désarme le homme-mort au changement de mode
    // 🆕 REX 2026-07-08 : PRG_01 (position 1) s'exécute AVANT PRG_06 (position 6) — GrappinBusy lu
    // ici reflète donc le Busy du scan PRÉCÉDENT (retard d'1 scan, ~10ms, sur la détection du front
    // descendant). Sans impact pratique : très inférieur aux temps de réponse frein/contacteurs
    // (100-300ms, voir FB_Brake) — la commande n'a pas le temps de produire un mouvement réel.
    GrappinBusy         := PRG_06_WinchControl.instGrappin.Busy,
    NeutralXMem         := GVL_PERSISTENT.JoystickNeutralX,
    NeutralYMem         := GVL_PERSISTENT.JoystickNeutralY,
    BusCanOpenOP        := instDiagCanOpen.busCanOpen,
    JoystickOP          := instDiagCanOpen.Joystick,
    RawX                := SEL(instSimJoystick.Enable, JoyXRaw_ANA1, instSimJoystick.RawX),
    RawY                := SEL(instSimJoystick.Enable, JoyYRaw_ANA2, instSimJoystick.RawY),
    RawButton           := SEL(instSimJoystick.Enable, JoyBtnRaw, instSimJoystick.RawButton),
    Calibrate           := GVL_IHM.Joystick.Calibrate,
    InvertX             := FALSE,
    InvertY             := FALSE,
    Deadband            := 10.0,
    FilterTime          := TIME#100ms,
    AccelRate           := 50.0,
    DecelRate           := 150.0,
    DeadmanRearmTimeout := T#5M,    // 🔴 TEST BANC — défaut sûr T#10S, voir bandeau ci-dessus
    NeutralHoldTime     := T#1S     // 🔴 TEST BANC — défaut sûr T#500MS, voir bandeau ci-dessus
);

// === IMPLEMENTATION (corps du PROGRAM PRG_02_Encoders) ===

// 1. SIMULATION SUR BANC DE TEST (Lot 2, granularité indépendante M1/M2 — voir AF_Partie13)
// 🔧 REX 2026-07-08 : RawPos (VAR_IN_OUT) référence GVL_PERSISTENT.SimEncoderRawPosM1/M2 —
// survit à un reset froid comme le ferait un vrai codeur absolu physique (voir GVL_PERSISTENT.st).
instSimEncoderM1(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM1_IsReal,
    RelayFwd    := PRG_10_Outputs.M1RelayFwd,
    RelayRev    := PRG_10_Outputs.M1RelayRev,
    SpeedRefPct := PRG_06_WinchControl.instWinchM1.SpeedRamp.Current,
    PresetCmd   := (COD1_PresettTrigCmd = 2),
    PresetValue := COD1_PresetValue,
    SpeedScaleFactor := GVL_Simulation.EncoderSimSpeedFactor,  // 🔧 REX 2026-07-07 : confort de test
    // 🆕 REX 2026-07-08 (4) : injection saut de test (Concept 1 / Méca E) — 4096 = PointsPerRev/CableM_PerRev (8192/2.0)
    TestOffsetCmd := GVL_Simulation.InjectSyncDeviationM1,
    TestOffsetPts := REAL_TO_DINT(GVL_Simulation.SyncDeviationOffsetM * 4096.0),
    RawPos      := GVL_PERSISTENT.SimEncoderRawPosM1
);
instSimEncoderM2(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM2_IsReal,
    RelayFwd    := PRG_10_Outputs.M2RelayFwd,
    RelayRev    := PRG_10_Outputs.M2RelayRev,
    SpeedRefPct := PRG_06_WinchControl.instWinchM2.SpeedRamp.Current,
    PresetCmd   := (COD2_PresettTrigCmd = 2),
    PresetValue := COD2_PresetValue,
    SpeedScaleFactor := GVL_Simulation.EncoderSimSpeedFactor,  // 🔧 REX 2026-07-07 : confort de test
    // 🆕 REX 2026-07-08 (4) : injection saut de test (Concept 1 / Méca E)
    TestOffsetCmd := GVL_Simulation.InjectSyncDeviationM2,
    TestOffsetPts := REAL_TO_DINT(GVL_Simulation.SyncDeviationOffsetM * 4096.0),
    RawPos      := GVL_PERSISTENT.SimEncoderRawPosM2
);

// Aiguillage (par device — 🔧 REX 2026-07-07 : ne PAS utiliser Operational, forcé à TRUE en
// simulation par PRG_01_Diagnostics [SEL sur EncoderMx_IsReal] pour ne pas remonter de faux
// défaut bus — ça sélectionnait donc systématiquement COD1/COD2_PosValue [réel, figé à 0] au
// lieu de la position simulée, bloquant tout homing/mouvement testé en simulation.
IF GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM1_IsReal THEN
    M1_RawPosToUse := instSimEncoderM1.RawPosOut;
ELSE
    M1_RawPosToUse := COD1_PosValue;
END_IF;

IF GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.EncoderM2_IsReal THEN
    M2_RawPosToUse := instSimEncoderM2.RawPosOut;
ELSE
    M2_RawPosToUse := COD2_PosValue;
END_IF;

// 2. TREUIL M1 (Abs → Homing → Scale)
// 🔧 REX 2026-07-07 : Homing appelé AVANT Scale (et non l'inverse) — Scale lit HomingRefRaw en
// entrée ; si Scale s'exécutait avant Homing, un homing réussi au cycle N ne serait répercuté
// sur CablePosM qu'au cycle N+1, alors que instHomingM1.Busy (→ InReferencingMode côté
// FB_Safety_Winch) retombe dès le cycle N — décalage d'1 cycle qui désynchronise le garde-fou
// anti-transition de Méca A (bit7) et provoque un faux déclenchement PowerCutOff au cycle N+1
// (saut de position vu hors fenêtre "référencement en cours"). Homing ne dépend d'aucune sortie
// de Scale (RawPos vient d'instEncoderAbsM1) : aucune dépendance circulaire, réordonnancement sûr.
instEncoderAbsM1(
    Enable              := TRUE,
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Mode                := PRG_04_Modes.instModes.Mode,
    RawPosIn            := M1_RawPosToUse,
    AlarmsIn            := SEL(instSimEncoderM1.Enable, COD1_Alarms, 0),
    WarningsIn          := SEL(instSimEncoderM1.Enable, COD1_Warnings, 0),
    SlaveOperational    := PRG_01_Diagnostics.instDiagEthercat.EncoderM1.Operational OR instSimEncoderM1.Enable,
    PresetRequest       := instHomingM1.PresetRequest,
    PresetValue         := instHomingM1.PresetValue
);
COD1_PresettTrigCmd := instEncoderAbsM1.PresetTriggerCmd;
COD1_CodeSeqTrigCmd := instEncoderAbsM1.CodeSeqTriggerCmd;
COD1_PresetValue    := instEncoderAbsM1.PresetValueOut;

instHomingM1(
    Enable               := TRUE,
    Calib                := GVL_PERSISTENT.CalibM1,
    Reset                := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk      := PRG_00_Inputs.EmergencyStopOk,
    Mode                 := PRG_04_Modes.instModes.Mode,
    Home                 := GVL_IHM.WinchM1.CmdHome,          // 🔧 REX 2026-07-07 : fusion GVL_Encoder_Stub → GVL_IHM
    ConfirmCoherence     := GVL_IHM.WinchM1.ConfirmCoherence, // 🔧 REX 2026-07-07 : fusion GVL_Encoder_Stub → GVL_IHM
    TopPositionSensor    := PRG_00_Inputs.TopPositionSensor,
    TopSensorPositionM   := GVL_PERSISTENT.HomingTargetM1_M,
    FwdRevSpeedFeedbackOff := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback        := PRG_00_Inputs.M1BrakeFeedback,
    RawPos               := instEncoderAbsM1.RawPos,
    EncoderAvailable     := instEncoderAbsM1.EncoderAvailable,
    PresetAck            := instEncoderAbsM1.PresetAck,
    PresetNak            := instEncoderAbsM1.PresetNak,
    PointsPerRev         := 8192,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := 2.0
);

instEncoderScaleM1(
    RawPos          := instEncoderAbsM1.RawPos,
    HomingRefRaw    := instHomingM1.HomingRefRaw,
    CableM_PerRev   := 2.0,
    PointsPerRev    := 8192
);

// 3. TREUIL M2 (Abs → Homing → Scale)
instEncoderAbsM2(
    Enable              := TRUE,
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Mode                := PRG_04_Modes.instModes.Mode,
    RawPosIn            := M2_RawPosToUse,
    AlarmsIn            := SEL(instSimEncoderM2.Enable, COD2_Alarms, 0),
    WarningsIn          := SEL(instSimEncoderM2.Enable, COD2_Warnings, 0),
    SlaveOperational    := PRG_01_Diagnostics.instDiagEthercat.EncoderM2.Operational OR instSimEncoderM2.Enable,
    PresetRequest       := instHomingM2.PresetRequest,
    PresetValue         := instHomingM2.PresetValue
);
COD2_PresettTrigCmd := instEncoderAbsM2.PresetTriggerCmd;
COD2_CodeSeqTrigCmd := instEncoderAbsM2.CodeSeqTriggerCmd;
COD2_PresetValue    := instEncoderAbsM2.PresetValueOut;

instHomingM2(
    Enable               := TRUE,
    Calib                := GVL_PERSISTENT.CalibM2,
    Reset                := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk      := PRG_00_Inputs.EmergencyStopOk,
    Mode                 := PRG_04_Modes.instModes.Mode,
    Home                 := GVL_IHM.WinchM2.CmdHome,          // 🔧 REX 2026-07-07 : fusion GVL_Encoder_Stub → GVL_IHM
    ConfirmCoherence     := GVL_IHM.WinchM2.ConfirmCoherence, // 🔧 REX 2026-07-07 : fusion GVL_Encoder_Stub → GVL_IHM
    TopPositionSensor    := PRG_00_Inputs.TopPositionSensor,
    TopSensorPositionM   := GVL_PERSISTENT.HomingTargetM2_M,
    FwdRevSpeedFeedbackOff := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback        := PRG_00_Inputs.M2BrakeFeedback,
    RawPos               := instEncoderAbsM2.RawPos,
    EncoderAvailable     := instEncoderAbsM2.EncoderAvailable,
    PresetAck            := instEncoderAbsM2.PresetAck,
    PresetNak            := instEncoderAbsM2.PresetNak,
    PointsPerRev         := 8192,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := 2.0
);

instEncoderScaleM2(
    RawPos          := instEncoderAbsM2.RawPos,
    HomingRefRaw    := instHomingM2.HomingRefRaw,
    CableM_PerRev   := 2.0,
    PointsPerRev    := 8192
);

// 4. SÉCURITÉ DE BORNAGE ET INCOHÉRENCE
instEncoderSafetyM1(
    Enable          := TRUE,
    Reset           := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
    Mode            := PRG_04_Modes.instModes.Mode,
    CablePosM       := instEncoderScaleM1.CablePosM,
    HomingSuspect   := instHomingM1.HomingSuspect,
    PositionMinM    := -99.0,
    PositionMaxM    := 99.0
);
EncoderFaultPresentM1 := instEncoderSafetyM1.EncoderIncoherent;

instEncoderSafetyM2(
    Enable          := TRUE,
    Reset           := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
    Mode            := PRG_04_Modes.instModes.Mode,
    CablePosM       := instEncoderScaleM2.CablePosM,
    HomingSuspect   := instHomingM2.HomingSuspect,
    PositionMinM    := -99.0,
    PositionMaxM    := 99.0
);
EncoderFaultPresentM2 := instEncoderSafetyM2.EncoderIncoherent;

EncoderFaultPresent := EncoderFaultPresentM1 OR EncoderFaultPresentM2;

// === IMPLEMENTATION (corps du PROGRAM PRG_03_Safety) ===
// 1. Sécurité Treuil M1 instSafetyWinchM1( Enable := NOT PRG_04_Modes.instModes.InhibitM1, // 🆕 REX 2026-07-08 : inhibition mise en service (MAINT_N2) Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, SyncEnable := PRG_04_Modes.instModes.SyncEnable, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.Joystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.Joystick.Operational, EncoderAvailable := PRG_02_Encoders.instEncoderAbsM1.EncoderAvailable, ThermalFeedback := NOT PRG_00_Inputs.M1ThermalFeedback, BrakeThermalFeedback := NOT PRG_00_Inputs.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 SlackCableDetected := NOT PRG_00_Inputs.SlackCableSwitch, PhaseRotationOk := PRG_00_Inputs.PhaseRotationOk, TopPositionSensor := PRG_00_Inputs.TopPositionSensor, InReferencingMode := PRG_02_Encoders.instHomingM1.Busy, CablePosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM, CableLimitDescentM := GVL_PERSISTENT.CableLimitDescentM1_M, Direction := PRG_06_WinchControl.M1_Direction_Active, Homed := PRG_02_Encoders.instHomingM1.Homed, HomingSuspect := PRG_02_Encoders.instHomingM1.HomingSuspect, TopLimitM := GVL_PERSISTENT.HomingTargetM1_M, // 🔧 REX 2026-07-07 — Méca A/B/C (voir FB_Safety_Winch bandeau en-tête) FwdRevSpeedFeedbackOff := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff, BrakeFeedback := PRG_00_Inputs.M1BrakeFeedback, JoystickYNeutral := ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef) < 0.1, GrappinHoldStillActive := PRG_06_WinchControl.instGrappin.Busy, // Méca C — M1 doit rester immobile pendant le // grappin ; 1 cycle de retard accepté (PRG_03 // avant PRG_06 dans l'ordre de tâche), négligeable // 🆕 REX 2026-07-08 (4) — Méca E : M2 corrigé de l'offset grappin actif (0 si grappin absent/ouvert), // ramené dans le référentiel M1 — comparaison valable quel que soit l'état du grappin ExpectedOtherWinchPosM := PRG_02_Encoders.instEncoderScaleM2.CablePosM - PRG_06_WinchControl.instGrappin.ActiveOffsetM, GrappinBusy := PRG_06_WinchControl.instGrappin.Busy, CriticalSyncToleranceM := GVL_PERSISTENT.WinchCriticalSyncTolerance_M, OtherWinchInhibited := PRG_04_Modes.instModes.InhibitM2 // 🆕 REX 2026-07-08 (7) );
// 2. Sécurité Treuil M2 instSafetyWinchM2( Enable := NOT PRG_04_Modes.instModes.InhibitM2, // 🆕 REX 2026-07-08 : inhibition mise en service (MAINT_N2) Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, SyncEnable := PRG_04_Modes.instModes.SyncEnable, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.Joystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.Joystick.Operational, EncoderAvailable := PRG_02_Encoders.instEncoderAbsM2.EncoderAvailable, ThermalFeedback := NOT PRG_00_Inputs.M2ThermalFeedback, BrakeThermalFeedback := NOT PRG_00_Inputs.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 SlackCableDetected := NOT PRG_00_Inputs.SlackCableSwitch, PhaseRotationOk := PRG_00_Inputs.PhaseRotationOk, TopPositionSensor := PRG_00_Inputs.TopPositionSensor, InReferencingMode := PRG_02_Encoders.instHomingM2.Busy, CablePosM := PRG_02_Encoders.instEncoderScaleM2.CablePosM, CableLimitDescentM := GVL_PERSISTENT.CableLimitDescentM2_M, Direction := PRG_06_WinchControl.M2_Direction_Active, Homed := PRG_02_Encoders.instHomingM2.Homed, HomingSuspect := PRG_02_Encoders.instHomingM2.HomingSuspect, TopLimitM := GVL_PERSISTENT.HomingTargetM2_M, // 🔧 REX 2026-07-07 — Méca A/B (voir FB_Safety_Winch bandeau en-tête) — Méca C NON applicable // à M2 (c'est M2 qui bouge pendant le grappin, GrappinHoldStillActive reste FALSE) FwdRevSpeedFeedbackOff := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff, BrakeFeedback := PRG_00_Inputs.M2BrakeFeedback, JoystickYNeutral := ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef) < 0.1, GrappinHoldStillActive := FALSE, // 🔧 REX 2026-07-08 (5) : BUG CORRIGÉ — oublié côté M2 lors de l'ajout initial Méca E. // ExpectedOtherWinchPosM valait 0.0 par défaut (non câblé) → Méca E comparait CablePosM2 // à 0 au lieu de M1, déclenchement permanent dès que M2 > CriticalSyncToleranceM (2.0m) // du zéro codeur. M1 corrigé de l'offset grappin actif, ramené dans le référentiel M2. ExpectedOtherWinchPosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM + PRG_06_WinchControl.instGrappin.ActiveOffsetM, GrappinBusy := PRG_06_WinchControl.instGrappin.Busy, CriticalSyncToleranceM := GVL_PERSISTENT.WinchCriticalSyncTolerance_M, OtherWinchInhibited := PRG_04_Modes.instModes.InhibitM1 // 🆕 REX 2026-07-08 (7) );
// 3. Sécurité Chariot M3 instSafetyChariotM3( Enable := TRUE, Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.Joystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.Joystick.Operational, PhaseRotationOk := PRG_00_Inputs.PhaseRotationOk, BrakeThermalFeedback := NOT PRG_00_Inputs.BrakeThermalFeedback // 🆕 REX 2026-07-08 — commun M1/M2/M3 );

// === IMPLEMENTATION (corps du PROGRAM PRG_04_Modes) ===

// 🆕 Exclusion mutuelle des inhibitions de treuils (soit M1, soit M2, jamais les deux)
IF GVL_IHM.WinchM1.CmdInhibit AND GVL_IHM.WinchM2.CmdInhibit THEN
    // Si M1 était déjà activé, on rejette la demande sur M2 (M2 retombe à FALSE)
    IF PrevInhibitM1 THEN
        GVL_IHM.WinchM2.CmdInhibit := FALSE;
    // Si M2 était déjà activé, on rejette la demande sur M1 (M1 retombe à FALSE)
    ELSIF PrevInhibitM2 THEN
        GVL_IHM.WinchM1.CmdInhibit := FALSE;
    ELSE
        // repli de sécurité si les deux s'activent de façon synchrone sans transition
        GVL_IHM.WinchM1.CmdInhibit := FALSE;
        GVL_IHM.WinchM2.CmdInhibit := FALSE;
    END_IF;
END_IF;

PrevInhibitM1 := GVL_IHM.WinchM1.CmdInhibit;
PrevInhibitM2 := GVL_IHM.WinchM2.CmdInhibit;

// 🆕 Si l'un des treuils est inhibé, synchro impossible par nature -> reset case IHM à TRUE
// (🔧 REX 2026-07-08 : polarité inversée, TRUE = état neutre "synchro voulue")
IF GVL_IHM.WinchM1.CmdInhibit OR GVL_IHM.WinchM2.CmdInhibit THEN
    GVL_IHM.Sync.SyncEnableRequest := TRUE;
END_IF;

instModes(
    Enable              := TRUE,
    Reset               := GVL_IHM.Modes.ModeReset,  // 🔧 REX 2026-07-07 : dédié, jamais mélangé au reset défauts général
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    ModeRequest         := GVL_Modes_Stub.ModeRequest_IHM,      // 🖥️ Sélecteur IHM
    SyncEnableRequest   := GVL_Modes_Stub.SyncEnableRequest_IHM,
    InhibitM1Request    := GVL_IHM.WinchM1.CmdInhibit, // 🆕 REX 2026-07-08 : IHM réelle, pas GVL_Modes_Stub
    InhibitM2Request    := GVL_IHM.WinchM2.CmdInhibit, // 🆕 REX 2026-07-08 : IHM réelle, pas GVL_Modes_Stub
    HomingApproachEnableRequest := GVL_IHM.Common.HomingApproachEnableRequest, // 🆕 REX 2026-07-08 (2)
    EncoderFaultPresent := PRG_02_Encoders.EncoderFaultPresent   // 1 cycle de retard (reçu de PRG_02_Encoders)
);

// === IMPLEMENTATION (corps du PROGRAM PRG_05_Cycle) ===
// Appel du séquenceur de cycle principal avec tous ses raccordements instCycle( Enable := (PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO), Reset := CmdResetCycle_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
StartCycle := CmdStartCycle_IHM, PauseCycle := CmdPauseCycle_IHM, AbortCycle := CmdAbortCycle_IHM,
TargetDepthM := TargetDepthM, TargetOffsetM := TargetOffsetM, SelectedTargetNum_IHM := GVL_IHM.Chariot.SelectedTargetNum,
// Capteur fond touché détecté par le mou de câble physique (sécurité positive) BottomTouched := NOT PRG_00_Inputs.SlackCableSwitch, M1_CablePosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM, M2_CablePosM := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
// Position chariot Chariot_At_Fosse1 := PRG_00_Inputs.ChariotPosFosse1, Chariot_At_Fosse2 := PRG_00_Inputs.ChariotPosFosse2, Chariot_At_Maintenance := PRG_00_Inputs.ChariotPosMaintenance, Chariot_At_Tremie := PRG_00_Inputs.ChariotPosTremie, Chariot_Busy := PRG_07_ChariotControl.instChariotM3.Busy, Chariot_Done := PRG_07_ChariotControl.instChariotM3.Done,
// Mouvements mâchoires grappin (gérés par instGrappin) Grappin_Busy := PRG_06_WinchControl.instGrappin.Busy, Grappin_Done := PRG_06_WinchControl.instGrappin.Done, Grappin_IsOpen := GVL_PERSISTENT.GrappinState.IsOpen, Grappin_IsClosed := GVL_PERSISTENT.GrappinState.IsClosed );

// === IMPLEMENTATION (corps du PROGRAM PRG_06_WinchControl) ===

// ── 0. COMMANDE DU GRAPPIN (Séquence lente) ─────────────────────────────
// 🔧 REX 2026-07-08 : appelé EN PREMIER (avant l'arbitrage M1/M2 ci-dessous) — audit sécurité :
// l'ancien ordre (Grappin appelé après l'arbitrage) faisait que M1_StartStop_Active lisait
// instGrappin.Busy du scan PRÉCÉDENT, créant une fenêtre d'1 scan où M1 pouvait recevoir une
// commande manuelle au moment exact où le grappin démarre. instGrappin.M1_Busy/M2_Busy (ci-dessous)
// lisent en retour instWinchM1/M2.Busy du scan précédent (ces FB sont appelés plus loin, §6/§7) —
// acceptable : ça ne retarde que l'ACCEPTATION d'une nouvelle demande de ~1 scan (10ms), sans
// aucun impact sécurité (contrairement au cas inverse, qui pouvait faire bouger M1 pendant Busy).
instGrappin(
    Enable              := NOT PRG_04_Modes.instModes.InhibitM2
                           AND PRG_02_Encoders.instEncoderAbsM1.EncoderAvailable
                           AND PRG_02_Encoders.instEncoderAbsM2.EncoderAvailable, // 🆕 Sécurisé : nécessite les deux codeurs valides et M2 non-inhibé
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Mode                := PRG_04_Modes.instModes.Mode,
    CmdOpen_IHM         := GVL_IHM.Grappin.CmdOpen OR PRG_05_Cycle.instCycle.CmdGrappin_Open,
    CmdClose_IHM        := GVL_IHM.Grappin.CmdClose OR PRG_05_Cycle.instCycle.CmdGrappin_Close,
    JoystickY_StartStop := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop,
    JoystickY_Direction := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.Direction,
    CablePosM1          := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    CablePosM2          := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    HomedM1             := PRG_02_Encoders.instHomingM1.Homed,
    HomedM2             := PRG_02_Encoders.instHomingM2.Homed,
    M1_Busy             := instWinchM1.Busy,   // 🆕 REX 2026-07-08
    M2_Busy             := instWinchM2.Busy,   // 🆕 REX 2026-07-08
    ConfirmOpenPosition := GVL_IHM.Grappin.CmdConfirmOpenPosition, // 🆕 REX 2026-07-08 — bouton IHM référencement grappin ouvert
    ConfirmClosePosition:= GVL_IHM.Grappin.CmdConfirmClosePosition, // 🆕 REX 2026-07-08 — bouton IHM référencement grappin fermé
    Config              := GVL_PERSISTENT.GrappinConfig,
    TimeoutDuration     := GVL_IHM.Grappin.TimeoutDuration,
    GrappinState        := GVL_PERSISTENT.GrappinState,
    InhibitM1           := PRG_04_Modes.instModes.InhibitM1, // 🆕 REX 2026-07-08
    InhibitM2           := PRG_04_Modes.instModes.InhibitM2  // 🆕 REX 2026-07-08
);

// 🆕 REX 2026-07-08 (4) — Concept 1 (écart synchro mineur) : bit0 seul (écart position, hors
// incohérence commande bit1) ne fait plus de SafeStop (fast) — bloque StartStop → rampe de décél
// NORMALE. Recalage : voir SyncEnable=FALSE (MAINT_N2), procédure déjà existante (mou de câble).
SyncMinorDeviation := (instWinchSync.ErrorId AND 16#0001) <> 16#0000;

// 🔧 REX 2026-07-08 (5) — audit sécurité : ne bloque plus StartStop dans les 2 sens (déblocage
// impossible sans Reset+MAINT_N2, régression terrain constatée, écart mécanique transitoire
// normal à l'arrêt). SignedDeltaPosM > 0 = M1 plus "haut" que M2 : la montée (Direction=+1)
// aggrave cet écart, la descente (-1) le réduit — et inversement si < 0. Seul le sens aggravant
// reste bloqué ; Méca E (FB_Safety_Winch, écart critique 2.0m) et bit1 (incohérence commande)
// restent le filet réel si l'écart continue de dériver malgré cette autorisation directionnelle.
// 🆕 REX 2026-07-08 (6) : gate global SyncSoftStopEnable — FALSE (défaut) = ces 2 sorties
// restent FALSE en permanence (bit0 déjà géré en SafeStop fast classique ci-dessus, §5bis) ;
// TRUE = active le blocage directionnel (nouvelle fonctionnalité, opt-in).
SyncMinorDeviationBlocksUp   := GVL_PERSISTENT.SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM > 0.0);
SyncMinorDeviationBlocksDown := GVL_PERSISTENT.SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM < 0.0);

// ── 1. ARBITRAGE DES CONSIGNES M1 (Joystick vs Cycle Automatique) ────────
IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
    // 🔧 REX 2026-07-08 (7) — review : gate directionnel absent de cette branche (bug trouvé en
    // review code), le cycle auto pouvait aggraver un écart mineur sans aucune protection quand
    // SyncSoftStopEnable=TRUE. Ajouté ici, symétrique à la branche manuelle ci-dessous.
    M1_Direction_Active := PRG_05_Cycle.instCycle.CmdWinchM1_Direction;
    M1_StartStop_Active := PRG_05_Cycle.instCycle.CmdWinchM1_StartStop
                            AND NOT ((SyncMinorDeviationBlocksUp   AND (M1_Direction_Active = 1))
                                 OR  (SyncMinorDeviationBlocksDown AND (M1_Direction_Active = -1)));
    M1_SpeedRef_Active  := PRG_05_Cycle.instCycle.CmdWinchM1_SpeedPct;
ELSE
    // 🔧 REX 2026-07-08 : + AND DeadmanArmed — NOT Busy seul insuffisant (rampe joystick met du
    // temps à redescendre à 0 après désarmement homme-mort ⇒ StartStop reste TRUE le temps de la
    // décél, M1 bougeait/frein décollait à la fin d'un cycle grappin). DeadmanArmed reste FALSE
    // en continu jusqu'au repassage neutre + réappui, sans dépendre du temps de rampe.
    // 🔧 REX 2026-07-08 (5) : Direction assignée AVANT StartStop (nécessaire pour le gate directionnel ci-dessous).
    M1_Direction_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.Direction;
    M1_StartStop_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop AND NOT instGrappin.Busy
                            AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                            AND NOT ((SyncMinorDeviationBlocksUp   AND (M1_Direction_Active = 1))
                                 OR  (SyncMinorDeviationBlocksDown AND (M1_Direction_Active = -1))); // 🔧 REX 2026-07-08 (5)
    M1_SpeedRef_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef;
END_IF;

// ── 2. ARBITRAGE DES CONSIGNES M2 (Grappin vs Cycle Automatique vs Joystick) ──
IF instGrappin.Busy THEN
    M2_StartStop_Active := instGrappin.M2_StartStop;
    M2_Direction_Active := instGrappin.M2_Direction;
    M2_SpeedRef_Active  := 15.0; // Vitesse lente forcée pour fermeture grappin
ELSE
    IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
        // 🔧 REX 2026-07-08 (7) — review : gate directionnel absent de cette branche, ajouté
        // symétrique à la branche manuelle ci-dessous (signe M2, voir note ci-dessous).
        M2_Direction_Active := PRG_05_Cycle.instCycle.CmdWinchM2_Direction;
        M2_StartStop_Active := PRG_05_Cycle.instCycle.CmdWinchM2_StartStop
                                AND NOT ((SyncMinorDeviationBlocksUp   AND (M2_Direction_Active = -1))
                                     OR  (SyncMinorDeviationBlocksDown AND (M2_Direction_Active = 1)));
        M2_SpeedRef_Active  := PRG_05_Cycle.instCycle.CmdWinchM2_SpeedPct;
    ELSE
        // 🔧 REX 2026-07-08 : + AND DeadmanArmed, même raison que M1 ci-dessus
        // 🔧 REX 2026-07-08 (5) : Direction assignée AVANT StartStop (gate directionnel)
        // 🐛 REX 2026-07-08 (7) — BUG CORRIGÉ (review code) : signe inversé pour M2. SignedDeltaPosM
        // (référentiel M1 : CablePosM1-CablePosM2+Offset) > 0 signifie M1 en avance — pour RATTRAPER,
        // M2 doit MONTER (+1), pas descendre. Donc BlocksUp (écart M1-en-avance) doit bloquer côté M2
        // le sens qui AGGRAVE, c-à-d Direction=-1 (descendre, M2 prend encore plus de retard) — PAS
        // Direction=+1 (monter, qui RATTRAPE). Symétrique inversé par rapport à M1 (qui utilise +1/-1
        // directement car SignedDeltaPosM est déjà dans SON référentiel).
        M2_Direction_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.Direction;
        M2_StartStop_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop
                                AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                AND NOT ((SyncMinorDeviationBlocksUp   AND (M2_Direction_Active = -1))
                                     OR  (SyncMinorDeviationBlocksDown AND (M2_Direction_Active = 1))); // 🔧 REX 2026-07-08 (7)
        M2_SpeedRef_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef;
    END_IF;
END_IF;

// ── 2bis. COUPURE IMMÉDIATE M1/M2 AU SCAN EXACT DE FIN DE CYCLE GRAPPIN ─────
// 🆕 REX 2026-07-08 : instGrappin est appelé en premier (§0), donc son Busy est frais dans CE scan
// (voir §1/§2 ci-dessus) — mais AxisCmdY.StartStop/Direction viennent de FB_Joystick_0 (PRG_01),
// calculé AVANT ce scan de PRG_06. Le désarmement homme-mort sur front descendant de Grappin.Busy
// (FB_Joystick §4ter-ter) ne prend donc effet qu'au scan SUIVANT (~10ms de retard structurel). Si
// l'opérateur tient encore le manche poussé au moment exact où le grappin termine, M1 ET M2
// recevaient pendant ce scan la commande manche brute (RelayFwd/Rev + BrakeCmd qui s'engage puis se
// coupe aussitôt = "clignotement" du frein, constaté sur site). On force ici l'arrêt immédiat,
// sans attendre le désarmement (qui reste nécessaire pour la suite : repassage au neutre exigé).
GrappinBusyFallEdge(CLK := instGrappin.Busy);
IF GrappinBusyFallEdge.Q THEN
    M1_StartStop_Active := FALSE;
    M2_StartStop_Active := FALSE;
END_IF;

// ── 3. SURVEILLANCE ÉCART DE SYNCHRONISATION ────────────────────────────
instWinchSync(
    Enable          := PRG_04_Modes.instModes.SyncEnable AND NOT instGrappin.Busy
                        AND NOT PRG_04_Modes.instModes.InhibitM1 AND NOT PRG_04_Modes.instModes.InhibitM2, // 🆕 REX 2026-07-08 : évite un faux défaut synchro pendant un test treuil seul
    Reset           := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
    Mode            := PRG_04_Modes.instModes.Mode,
    CablePosM1      := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    CablePosM2      := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    HomedM1         := PRG_02_Encoders.instHomingM1.Homed,
    HomedM2         := PRG_02_Encoders.instHomingM2.Homed,
    SyncEnable      := PRG_04_Modes.instModes.SyncEnable,
    SyncToleranceM  := GVL_PERSISTENT.WinchSyncTolerance_M,
    ActiveOffsetM   := instGrappin.ActiveOffsetM,

    RelayFwdM1      := instWinchM1.RelayFwd,
    RelayFwdM2      := instWinchM2.RelayFwd,
    RelayRevM1      := instWinchM1.RelayRev,
    RelayRevM2      := instWinchM2.RelayRev,
    Contactor1_M1   := instWinchM1.Contactor1,
    Contactor1_M2   := instWinchM2.Contactor1,
    Contactor2_M1   := instWinchM1.Contactor2,
    Contactor2_M2   := instWinchM2.Contactor2,
    Contactor3_M1   := instWinchM1.Contactor3,
    Contactor3_M2   := instWinchM2.Contactor3,
    Contactor4_M1   := instWinchM1.Contactor4,
    Contactor4_M2   := instWinchM2.Contactor4
);

// Table active M2 (verrouille TOUS les paliers sur la combinaison réelle du palier 1 si
// vitesse lente requise pour le grappin — REX 2026-07-08 : l'ancienne version mettait
// TOUS les contacteurs à FALSE pour tous les paliers, y compris le palier 1 lui-même, ce qui
// donnait un mouvement à vitesse quasi nulle/insuffisante (résistance rotorique maximale, aucun
// contacteur de vitesse engagé). Le palier 1 réel (`WinchSpeedStepTable.P1Rx`) engage déjà le
// contacteur le plus lent prévu pour un fonctionnement normal — on le duplique sur les 5 paliers
// pour que M2 reste TOUJOURS à cette vitesse pendant le grappin, quelle que soit l'amplitude
// joystick (peu importe le palier sélectionné par l'hystérésis, le résultat est identique).
IF instGrappin.M2_ForceSlowSpeed THEN
    M2_SpeedStepTableActive.P1R1 := GVL_PERSISTENT.WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P1R2 := GVL_PERSISTENT.WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P1R3 := GVL_PERSISTENT.WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P1R4 := GVL_PERSISTENT.WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P2R1 := GVL_PERSISTENT.WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P2R2 := GVL_PERSISTENT.WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P2R3 := GVL_PERSISTENT.WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P2R4 := GVL_PERSISTENT.WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P3R1 := GVL_PERSISTENT.WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P3R2 := GVL_PERSISTENT.WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P3R3 := GVL_PERSISTENT.WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P3R4 := GVL_PERSISTENT.WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P4R1 := GVL_PERSISTENT.WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P4R2 := GVL_PERSISTENT.WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P4R3 := GVL_PERSISTENT.WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P4R4 := GVL_PERSISTENT.WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P5R1 := GVL_PERSISTENT.WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P5R2 := GVL_PERSISTENT.WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P5R3 := GVL_PERSISTENT.WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P5R4 := GVL_PERSISTENT.WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.StepThreshold_Pct := GVL_PERSISTENT.WinchSpeedStepTable.StepThreshold_Pct;
ELSE
    M2_SpeedStepTableActive := GVL_PERSISTENT.WinchSpeedStepTable;
END_IF;

// ── 5. CALCUL DES LIMITES BASSES ACTIVES ET DU BLOCAGE DE DESCENTE ──────
// 🔧 REX 2026-07-07 : limite légale appliquée sur LimitLegalEnabled SEUL, plus de garde
// Mode=SEMI_AUTO — la limite légale doit stopper la descente dans TOUS les modes dès qu'elle
// est activée (constat terrain : ne s'arrêtait pas en MAINT_N1/N2 alors qu'attendu).
BottomLimitM1_Active := GVL_PERSISTENT.CableLimitDescentM1_M;
IF GVL_PERSISTENT.LimitLegalEnabled THEN
    BottomLimitM1_Active := MAX(BottomLimitM1_Active, GVL_PERSISTENT.LimitLegalDepthMinAllowed);
END_IF;

BottomLimitM2_Active := GVL_PERSISTENT.CableLimitDescentM2_M;
IF GVL_PERSISTENT.LimitLegalEnabled THEN
    BottomLimitM2_Active := MAX(BottomLimitM2_Active, GVL_PERSISTENT.LimitLegalDepthMinAllowed);
END_IF;

// ── 5bis. COUPLAGE CROISÉ M1/M2 — REX 2026-07-07 ────────────────────────
// Hors synchro (Grappin.Busy ou SyncEnable=FALSE N2) : chaque treuil réagit à SA PROPRE limite/
// défaut uniquement (commande indépendante voulue). En synchro (SyncActive, mouvement cohérent
// voulu) : n'importe quel arrêt (SafeStop, limite câble, limite légale, fin de course haut) sur
// UN treuil coupe IMMÉDIATEMENT les deux — pas d'attente du filtre 500ms de FB_WinchSync.
// 🔧 REX 2026-07-07 : instGrappin.M1SlipDetected ajouté à M1 uniquement (Méca C couche 1) — M2
// est déjà arrêté par son propre mécanisme SevereError interne à FB_Grappin, pas besoin ici.
// 🔧 REX 2026-07-08 (4) : instWinchSync.Error (bit0+bit1) → SEUL bit1 (incohérence commande,
// grave) reste ici en SafeStop fast. Bit0 (écart mineur) → arrêt rampe normale via StartStop
// (voir SyncMinorDeviation, §1/§2 plus haut) — Concept 1, ne pas dégrader le comportement voulu.
// 🆕 REX 2026-07-08 (6) : GVL_PERSISTENT.SyncSoftStopEnable=FALSE (défaut) → comportement D'AVANT,
// bit0 réintégré ici en SafeStop fast classique comme n'importe quel autre défaut winch. TRUE →
// bit0 exclu d'ici, géré exclusivement par le gate directionnel StartStop (§1/§2).
SafeStopM1_Raw      := PRG_03_Safety.instSafetyWinchM1.SafeStop
                       OR ((instWinchSync.ErrorId AND 16#0002) <> 16#0000)
                       OR (NOT GVL_PERSISTENT.SyncSoftStopEnable AND ((instWinchSync.ErrorId AND 16#0001) <> 16#0000))
                       OR instGrappin.M1SlipDetected;
SafeStopM2_Raw      := PRG_03_Safety.instSafetyWinchM2.SafeStop
                       OR ((instWinchSync.ErrorId AND 16#0002) <> 16#0000)
                       OR (NOT GVL_PERSISTENT.SyncSoftStopEnable AND ((instWinchSync.ErrorId AND 16#0001) <> 16#0000));

ForbidDescentM1_Raw := PRG_03_Safety.instSafetyWinchM1.ForbidDescent
                       OR (GVL_PERSISTENT.LimitLegalEnabled
                           AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM <= GVL_PERSISTENT.LimitLegalDepthMinAllowed));
ForbidDescentM2_Raw := PRG_03_Safety.instSafetyWinchM2.ForbidDescent
                       OR (GVL_PERSISTENT.LimitLegalEnabled
                           AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM <= GVL_PERSISTENT.LimitLegalDepthMinAllowed));

// 🔧 REX 2026-07-08 : arrêt réel encodeur en fonctionnement NORMAL, distinct du capteur physique
// (bit5 côté FB_Safety_Winch). Seuil = HomingTargetMx_M - WinchTopStopMarginM (RELATIF à la
// position haute de référence, pas une valeur absolue) : si HomingTargetMx_M est recalibrée sur
// site, la position d'arrêt normal suit automatiquement, toujours à la même marge du capteur.
// Même principe que la limite légale de descente ci-dessus (condition LIVE, pas de bit
// ErrorId/Reset dédié) — passe par ForbidAscentMx_Raw pour bénéficier DU MÊME couplage croisé
// M1/M2 que le capteur physique (sinon un treuil qui atteint la limite une fraction de seconde
// avant l'autre crée un écart RelayFwdM1<>RelayFwdM2 qui déclenche à tort le défaut FB_WinchSync
// bit1 "incohérence de commande" — REX terrain 2026-07-08, testé et corrigé).
// homing), sans qu'aucun bit dédié ne soit requis. Remplacé par `HomingApproachEnable` (FB_Modes,
// même pattern que SyncEnable) : nécessite MAINT_N2 ET une case IHM activée consciemment.
ForbidAscentM1_Raw  := PRG_03_Safety.instSafetyWinchM1.ForbidAscent
                       OR (PRG_02_Encoders.instHomingM1.Homed
                           AND NOT PRG_02_Encoders.instHomingM1.HomingSuspect
                           AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM >= GVL_PERSISTENT.HomingTargetM1_M))
                       OR (PRG_02_Encoders.instHomingM1.Homed
                           AND NOT PRG_02_Encoders.instHomingM1.HomingSuspect
                           AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM >=
                                (GVL_PERSISTENT.HomingTargetM1_M - GVL_PERSISTENT.WinchTopStopMarginM))
                           AND NOT PRG_04_Modes.instModes.HomingApproachEnable);
// 🐛 REX 2026-07-08 (7) — BUG CORRIGÉ (retour terrain) / REX 2026-07-08 (2) :
// La butée haute de M2 n'est décalée de l'OffsetCloseM QUE si le grappin est fermé (IsClosed)
// ou en cours de fermeture (CloseReq). Sinon (grappin ouvert/en cours d'ouverture), M2 doit
// s'arrêter à la butée normale de 12.00m (HomingTargetM2_M - margin) pour s'arrêter proprement en même temps que M1.
M2_LimitShift := SEL(GVL_PERSISTENT.GrappinState.IsClosed OR instGrappin.CloseReq, 0.0, GVL_PERSISTENT.GrappinConfig.OffsetCloseM);

ForbidAscentM2_Raw  := PRG_03_Safety.instSafetyWinchM2.ForbidAscent
                       OR (PRG_02_Encoders.instHomingM2.Homed
                           AND NOT PRG_02_Encoders.instHomingM2.HomingSuspect
                           AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM >= (GVL_PERSISTENT.HomingTargetM2_M + M2_LimitShift)))
                       OR (PRG_02_Encoders.instHomingM2.Homed
                           AND NOT PRG_02_Encoders.instHomingM2.HomingSuspect
                           AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM >=
                                (GVL_PERSISTENT.HomingTargetM2_M + M2_LimitShift - GVL_PERSISTENT.WinchTopStopMarginM))
                           AND NOT PRG_04_Modes.instModes.HomingApproachEnable);

SafeStopM1_Active      := SafeStopM1_Raw      OR (instWinchSync.SyncActive AND SafeStopM2_Raw);
SafeStopM2_Active      := SafeStopM2_Raw      OR (instWinchSync.SyncActive AND SafeStopM1_Raw);
ForbidDescentM1_Active := ForbidDescentM1_Raw OR (instWinchSync.SyncActive AND ForbidDescentM2_Raw);
ForbidDescentM2_Active := ForbidDescentM2_Raw OR (instWinchSync.SyncActive AND ForbidDescentM1_Raw);
ForbidAscentM1_Active  := ForbidAscentM1_Raw  OR (instWinchSync.SyncActive AND ForbidAscentM2_Raw);
ForbidAscentM2_Active  := ForbidAscentM2_Raw  OR (instWinchSync.SyncActive AND ForbidAscentM1_Raw);

// ── 6. EXÉCUTION DU PILOTAGE DU TREUIL M1 ───────────────────────────────
instWinchM1(
    Enable                  := StubMachineEnableN1 AND NOT PRG_04_Modes.instModes.InhibitM1, // 🆕 REX 2026-07-08
    Reset                   := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk         := PRG_00_Inputs.EmergencyStopOk,
    Mode                    := PRG_04_Modes.instModes.Mode,
    StartStop               := M1_StartStop_Active,
    SafeStop                := SafeStopM1_Active,
    ForbidDescent           := ForbidDescentM1_Active,
    ForbidAscent            := ForbidAscentM1_Active,
    Direction               := M1_Direction_Active,
    SpeedRefPct             := M1_SpeedRef_Active,
    SpeedStepTable          := GVL_PERSISTENT.WinchSpeedStepTable,
    MaxStepDescente         := GVL_PERSISTENT.WinchMaxStepDescente, // 🔧 REX 2026-07-08 : commun M1/M2
    HomingApproachActive    := PRG_04_Modes.instModes.HomingApproachEnable, // 🆕 REX 2026-07-08 : vitesse lente en approche
    FwdRevSpeedFeedbackOff  := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback           := PRG_00_Inputs.M1BrakeFeedback,
    BypassContactorCheck    := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM1_IsReal,
    RampAccelRate           := GVL_PERSISTENT.WinchM1RampAccelRate_Pct,
    RampDecelNormalRate     := GVL_PERSISTENT.WinchM1RampDecelNormal_Pct,
    RampDecelFastRate       := GVL_PERSISTENT.WinchM1RampDecelFast_Pct,
    Homed                   := PRG_02_Encoders.instHomingM1.Homed,
    HomingSuspect           := PRG_02_Encoders.instHomingM1.HomingSuspect, // 🆕 Câblage de l'incertitude M1
    CablePosM               := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    TopLimitM               := GVL_PERSISTENT.HomingTargetM1_M,
    BottomLimitM            := BottomLimitM1_Active,
    SlowdownDistanceM       := GVL_PERSISTENT.WinchSlowdownDistance_M,
    SlowSpeedPct            := GVL_PERSISTENT.WinchSlowSpeedPct
);

// ── 7. EXÉCUTION DU PILOTAGE DU TREUIL M2 ───────────────────────────────
instWinchM2(
    Enable                  := StubMachineEnableN1 AND NOT PRG_04_Modes.instModes.InhibitM2, // 🆕 REX 2026-07-08
    Reset                   := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk         := PRG_00_Inputs.EmergencyStopOk,
    Mode                    := PRG_04_Modes.instModes.Mode,
    StartStop               := M2_StartStop_Active,
    SafeStop                := SafeStopM2_Active,
    ForbidDescent           := ForbidDescentM2_Active,
    ForbidAscent            := ForbidAscentM2_Active,
    Direction               := M2_Direction_Active,
    SpeedRefPct             := M2_SpeedRef_Active,
    SpeedStepTable          := M2_SpeedStepTableActive,
    MaxStepDescente         := GVL_PERSISTENT.WinchMaxStepDescente, // 🔧 REX 2026-07-08 : commun M1/M2
    HomingApproachActive    := PRG_04_Modes.instModes.HomingApproachEnable, // 🆕 REX 2026-07-08 : vitesse lente en approche
    FwdRevSpeedFeedbackOff  := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback           := PRG_00_Inputs.M2BrakeFeedback,
    BypassContactorCheck    := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM2_IsReal,
    RampAccelRate           := GVL_PERSISTENT.WinchM2RampAccelRate_Pct,
    RampDecelNormalRate     := GVL_PERSISTENT.WinchM2RampDecelNormal_Pct,
    RampDecelFastRate       := GVL_PERSISTENT.WinchM2RampDecelFast_Pct,
    Homed                   := PRG_02_Encoders.instHomingM2.Homed,
    HomingSuspect           := PRG_02_Encoders.instHomingM2.HomingSuspect, // 🆕 Câblage de l'incertitude M2
    CablePosM               := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    TopLimitM               := GVL_PERSISTENT.HomingTargetM2_M + M2_LimitShift,
    BottomLimitM            := BottomLimitM2_Active,
    SlowdownDistanceM       := GVL_PERSISTENT.WinchSlowdownDistance_M,
    SlowSpeedPct            := GVL_PERSISTENT.WinchSlowSpeedPct
);

// ── 8. ALIMENTATION PRG_10_Outputs (sorties physiques) ──────────────────
// 🔴🔧 REX 2026-07-07 : PRG_10_Outputs est une tâche indépendante (MainTask, PouList),
// jamais appelée avec paramètres — ses VAR_INPUT restaient à FALSE en permanence, y compris
// sur machine réelle (aucun relais/contacteur/frein ne s'activait jamais). Alimentation directe
// ici, AVANT PRG_10_Outputs dans l'ordre de tâche (position 6 < 10, même cycle API).
PRG_10_Outputs.M1RelayFwd        := instWinchM1.RelayFwd;
PRG_10_Outputs.M1RelayRev        := instWinchM1.RelayRev;
PRG_10_Outputs.M1SpeedContactor1 := instWinchM1.Contactor1;
PRG_10_Outputs.M1SpeedContactor2 := instWinchM1.Contactor2;
PRG_10_Outputs.M1SpeedContactor3 := instWinchM1.Contactor3;
PRG_10_Outputs.M1SpeedContactor4 := instWinchM1.Contactor4;
PRG_10_Outputs.M1BrakeCmd        := instWinchM1.BrakeCmd;

PRG_10_Outputs.M2RelayFwd        := instWinchM2.RelayFwd;
PRG_10_Outputs.M2RelayRev        := instWinchM2.RelayRev;
PRG_10_Outputs.M2SpeedContactor1 := instWinchM2.Contactor1;
PRG_10_Outputs.M2SpeedContactor2 := instWinchM2.Contactor2;
PRG_10_Outputs.M2SpeedContactor3 := instWinchM2.Contactor3;
PRG_10_Outputs.M2SpeedContactor4 := instWinchM2.Contactor4;
PRG_10_Outputs.M2BrakeCmd        := instWinchM2.BrakeCmd;

// === IMPLEMENTATION (corps du PROGRAM PRG_07_ChariotControl) ===

// ── 1. ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ──────────────────
IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
    // Mode Auto/Semi-Auto : Consigne issue du séquenceur de cycle
    SelectedTargetNum    := PRG_05_Cycle.instCycle.CmdChariotM3_Target;
    M3_StartStop_Active  := PRG_05_Cycle.instCycle.CmdChariotM3_Start;
    M3_SpeedRef_Active   := 40.0; // Vitesse de translation automatique nominale (40%)

    // Détermination automatique du sens de marche selon la cible :
    // - Trémie (cible 4) = Marche Avant (Direction := 1)
    // - Fosses (cible 1 et 2) = Marche Arrière (Direction := -1)
    IF SelectedTargetNum = 4 THEN
        M3_Direction_Active := 1;
    ELSE
        M3_Direction_Active := -1;
    END_IF;
ELSE
    // Mode Manuel/Maintenance : Consignes issues du Joystick et sélecteur HMI
    SelectedTargetNum    := StubChariotPositionSelect_IHM;
    M3_StartStop_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.StartStop;
    M3_Direction_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.Direction;
    M3_SpeedRef_Active   := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.SpeedRef;
END_IF;

// Câblage du capteur de butée de la cible sélectionnée
CASE SelectedTargetNum OF
    1: M3_PositionSensorTarget := PRG_00_Inputs.ChariotPosFosse1;
    2: M3_PositionSensorTarget := PRG_00_Inputs.ChariotPosFosse2;
    3: M3_PositionSensorTarget := PRG_00_Inputs.ChariotPosMaintenance;
    4: M3_PositionSensorTarget := PRG_00_Inputs.ChariotPosTremie;
ELSE
    M3_PositionSensorTarget := FALSE;   // Aucun capteur visé
END_CASE;

// ── 2. EXÉCUTION DU PILOTAGE DU CHARIOT M3 ──────────────────────────────
instChariotM3(
    Enable                  := PRG_06_WinchControl.StubMachineEnableN1,
    Reset                   := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk         := PRG_00_Inputs.EmergencyStopOk,
    Mode                    := PRG_04_Modes.instModes.Mode,
    StartStop               := M3_StartStop_Active,
    SafeStop                := PRG_03_Safety.instSafetyChariotM3.SafeStop,
    CommMode                := E_ChariotCommMode.DEGRADED_IO,
    Direction               := M3_Direction_Active,
    SpeedRefPct             := M3_SpeedRef_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    DriveStatusWord         := 0,
    DriveActualFreqHz       := 0.0,
    ContactorFeedbackFwd    := M3_ContactorFeedbackFwd,
    ContactorFeedbackRev    := M3_ContactorFeedbackRev,
    DriveFaultFeedback      := M3_DriveFaultFeedback,
    BrakeFeedback           := SEL(GVL_IHM.Chariot.BypassBrakeFeedback, PRG_00_Inputs.M3BrakeFeedback, instChariotM3.BrakeCmd),
    BypassContactorCheck    := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM3_IsReal
);

// ── 3. RECOPIE VERS LES VARIABLES GLOBALES DE SIMULATION / STUBS ─────────
M3_RelayFwd     := instChariotM3.RelayFwd;
M3_RelayRev     := instChariotM3.RelayRev;
M3_RelaySpeedGv := instChariotM3.RelaySpeedGv;

// 🔴🔧 REX 2026-07-07 : alimentation PRG_10_Outputs (tâche indépendante, jamais appelée avec
// paramètres — voir même correctif dans PRG_06_WinchControl.st §8).
PRG_10_Outputs.ChariotBrakeCmd := instChariotM3.BrakeCmd;

// 🧪 Retour contacteur M3 (Lot 5, non prioritaire) : miroir temporisé réaliste
// (FB_Sim_DigitalMirror) au lieu de l'ancien miroir instantané inconditionnel.
// Délai nettement sous ContactorFeedbackTimeout (500ms, GVL_PERSISTENT côté FB_Chariot)
// pour ne pas déclencher StuckClosed/StuckOpen à tort pendant le délai simulé.
instSimMirrorM3Fwd(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM3_IsReal,
    Command     := M3_RelayFwd,
    MirrorDelay := T#150ms
);
instSimMirrorM3Rev(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.ContactorFeedbackM3_IsReal,
    Command     := M3_RelayRev,
    MirrorDelay := T#150ms
);
M3_ContactorFeedbackFwd := instSimMirrorM3Fwd.Feedback;
M3_ContactorFeedbackRev := instSimMirrorM3Rev.Feedback;

// === IMPLEMENTATION (corps du PROGRAM PRG_08_AuxiliaryControl) ===

// --- STUBS LOGIQUES TEMPORAIRES (comportement passif / neutre) ---
HydraulicPumpRunCmd := FALSE;
SifterRunCmd        := FALSE;
GridOpenCmd         := FALSE;
HelmetCloseCmd      := FALSE;

HydraulicFaultOk    := TRUE; // Par défaut sain (NC)
SifterFaultOk       := TRUE; // Par défaut sain (NC)

// === IMPLEMENTATION (corps du PROGRAM PRG_09_Supervision) ===

// ── 1. ACQUISITION DES DEMANDES / BOUTONS DE L'IHM ────────────────────────
GVL_Modes_Stub.ModeRequest_IHM         := GVL_IHM.Modes.ModeRequest;
GVL_Modes_Stub.SyncEnableRequest_IHM   := GVL_IHM.Sync.SyncEnableRequest; // 🔧 REX 2026-07-08 : renommé, polarité inversée
StubChariotPositionSelect_IHM          := GVL_IHM.Chariot.SelectedTargetNum;

// Signal d'acquittement défauts domaine sécurité/métier — JAMAIS Modes/Cycle (REX 2026-07-07)
FaultMachineReset_IHM := GVL_IHM.Modes.FaultMachineReset
                    OR GVL_IHM.WinchM1.CmdReset
                    OR GVL_IHM.WinchM2.CmdReset
                    OR GVL_IHM.Grappin.CmdReset;

// 🔴 REX 2026-07-07 : au moins un défaut actif dans le domaine couvert par FaultMachineReset_IHM
// (même périmètre exact que les 17 blocs alimentés par ce reset — voir bandeau en tête de fichier).
// Sert à savoir, côté IHM, quand un appui sur FaultMachineReset est utile/attendu.
GVL_IHM.Modes.AnyFaultActive :=
       PRG_01_Diagnostics.instDiagCanOpen.Error
    OR PRG_01_Diagnostics.instDiagEthercat.Error
    OR PRG_01_Diagnostics.FB_Joystick_0.Error
    OR (NOT PRG_04_Modes.instModes.InhibitM1 AND (
           PRG_02_Encoders.instEncoderAbsM1.Error
        OR PRG_02_Encoders.instHomingM1.Error
        OR PRG_02_Encoders.instEncoderSafetyM1.Error
        OR PRG_03_Safety.instSafetyWinchM1.Error
        OR PRG_06_WinchControl.instWinchM1.Error
    ))
    OR (NOT PRG_04_Modes.instModes.InhibitM2 AND (
           PRG_02_Encoders.instEncoderAbsM2.Error
        OR PRG_02_Encoders.instHomingM2.Error
        OR PRG_02_Encoders.instEncoderSafetyM2.Error
        OR PRG_03_Safety.instSafetyWinchM2.Error
        OR PRG_06_WinchControl.instWinchM2.Error
    ))
    OR PRG_03_Safety.instSafetyChariotM3.Error
    OR PRG_06_WinchControl.instWinchSync.Error
    OR PRG_06_WinchControl.instGrappin.Error
    OR PRG_07_ChariotControl.instChariotM3.Error
    OR PRG_10_Outputs.RedundancyTestFailed
    OR PRG_10_Outputs.EmergencyArmingFailed;

// 🧨 REX 2026-07-07 : remontée IHM de la coupure puissance amont — polarité "alarme" (TRUE=
// problème), PAS celle de PowerCutOff_A_RQ (qui est en fail-safe maintenu, TRUE=OK depuis
// l'inversion de polarité). On relit directement les .PowerCutOff sources, pas la sortie physique.
GVL_IHM.Modes.PowerCutOffActive := PRG_03_Safety.instSafetyWinchM1.PowerCutOff
                                 OR PRG_03_Safety.instSafetyWinchM2.PowerCutOff
                                 OR PRG_03_Safety.instSafetyChariotM3.PowerCutOff
                                 OR GVL_IHM.Modes.CmdEmergencyCutOff;

// 🆕 REX 2026-07-08 : thermique frein commun M1/M2/M3 — signal UNIQUE (1 seul fil, pas de sens à
// le dupliquer par axe), remonté une seule fois au niveau global GVL_IHM (même principe que
// TopPositionSensorActive ci-dessus, PAS dans WinchM1/WinchM2/Chariot).
GVL_IHM.Common.BrakeThermalFault := NOT PRG_00_Inputs.BrakeThermalFeedback;
GVL_IHM.Common.PhaseRotationFault := NOT PRG_00_Inputs.PhaseRotationOk; // 🆕 REX 2026-07-08 — commun M1/M2/M3, invisible IHM avant

// 🔧 REX 2026-07-07 — Séquence réarmement AU (voir DOC/AF_Partie1 v1.5 §Sécurité électrique)
// EmergencyArmingBusy couvre TOUTE la séquence (auto-test A/B + pulse + confirmation + verrouillage),
// pas seulement le pulse — ArmingSeqStep<>0 englobe déjà tout sauf le verrouillage final.
GVL_IHM.Modes.EmergencyChainOk    := PRG_00_Inputs.EmergencyChain;
GVL_IHM.Modes.PowerContactorOk    := PRG_00_Inputs.EmergencyStopOk;
GVL_IHM.Modes.EmergencyArmingBusy := (PRG_10_Outputs.ArmingSeqStep <> 0) OR PRG_10_Outputs.EmergencyArmingLockoutActive;
GVL_IHM.Modes.EmergencyArmable    := PRG_00_Inputs.EmergencyChain
                                    AND (PRG_10_Outputs.ArmingSeqStep = 0)
                                    AND NOT PRG_10_Outputs.EmergencyArmingLockoutActive
                                    AND NOT PRG_10_Outputs.RedundancyTestFailed;
GVL_IHM.Modes.RedundancyTestFailed := PRG_10_Outputs.RedundancyTestFailed;
GVL_IHM.Modes.EmergencyArmingFailed := PRG_10_Outputs.EmergencyArmingFailed;

// 🔧 REX 2026-07-07 : ancien pont IF/ELSIF vers GVL_Encoder_Stub supprimé (bugué — ne pouvait
// homer qu'un seul treuil à la fois). GVL_IHM.WinchM1/M2.CmdHome sont désormais câblés
// directement dans PRG_02_Encoders.st (instHomingM1/M2.Home) — homing simultané possible.

// ℹ️ Calibrate joystick : lu directement depuis GVL_IHM.Joystick.Calibrate dans PRG_01_Diagnostics (ligne 48)
// PRG_01_Diagnostics.FB_Joystick_0.Calibrate := GVL_IHM.Joystick.Calibrate;  // ❌ supprimé : VAR locale non accessible en écriture (C0037)


// ── 2. INITIALISATION IHM DEPUIS GVL_PERSISTENT (Boot) ───────────────────
IF GVL_IHM.WinchM1.TopSensorPositionM = 0.0 THEN
    GVL_IHM.WinchM1.TopSensorPositionM  := GVL_PERSISTENT.HomingTargetM1_M;
    GVL_IHM.WinchM1.MaxStepDescente     := GVL_PERSISTENT.WinchMaxStepDescente; // 🔧 REX 2026-07-08 : commun M1/M2
    GVL_IHM.WinchM1.RampAccelRate       := GVL_PERSISTENT.WinchM1RampAccelRate_Pct;
    GVL_IHM.WinchM1.RampDecelNormalRate := GVL_PERSISTENT.WinchM1RampDecelNormal_Pct;
    GVL_IHM.WinchM1.RampDecelFastRate   := GVL_PERSISTENT.WinchM1RampDecelFast_Pct;
    GVL_IHM.WinchM1.CableLimitDescentM  := GVL_PERSISTENT.CableLimitDescentM1_M;
    GVL_IHM.WinchM1.SlowdownDistanceM   := GVL_PERSISTENT.WinchSlowdownDistance_M;
    GVL_IHM.WinchM1.SlowSpeedPct        := GVL_PERSISTENT.WinchSlowSpeedPct;
END_IF;

IF GVL_IHM.WinchM2.TopSensorPositionM = 0.0 THEN
    GVL_IHM.WinchM2.TopSensorPositionM  := GVL_PERSISTENT.HomingTargetM2_M;
    GVL_IHM.WinchM2.MaxStepDescente     := GVL_PERSISTENT.WinchMaxStepDescente; // 🔧 REX 2026-07-08 : commun M1/M2
    GVL_IHM.WinchM2.RampAccelRate       := GVL_PERSISTENT.WinchM2RampAccelRate_Pct;
    GVL_IHM.WinchM2.RampDecelNormalRate := GVL_PERSISTENT.WinchM2RampDecelNormal_Pct;
    GVL_IHM.WinchM2.RampDecelFastRate   := GVL_PERSISTENT.WinchM2RampDecelFast_Pct;
    GVL_IHM.WinchM2.CableLimitDescentM  := GVL_PERSISTENT.CableLimitDescentM2_M;
    GVL_IHM.WinchM2.SlowdownDistanceM   := GVL_PERSISTENT.WinchSlowdownDistance_M;
    GVL_IHM.WinchM2.SlowSpeedPct        := GVL_PERSISTENT.WinchSlowSpeedPct;
END_IF;

IF GVL_IHM.Sync.SyncToleranceM = 0.0 THEN
    GVL_IHM.Sync.SyncToleranceM         := GVL_PERSISTENT.WinchSyncTolerance_M;
END_IF;

IF GVL_IHM.Grappin.Config.OffsetOpenM = 0.0 AND GVL_IHM.Grappin.Config.OffsetCloseM = 0.0 THEN
    GVL_IHM.Grappin.Config := GVL_PERSISTENT.GrappinConfig;
    GVL_IHM.Grappin.TimeoutDuration := T#30s;
END_IF;

IF GVL_IHM.Common.LimitLegalDepthMinAllowed = 0.0 THEN
    GVL_IHM.Common.LimitLegalDepthMinAllowed := GVL_PERSISTENT.LimitLegalDepthMinAllowed;
    GVL_IHM.Common.LimitLegalEnabled         := GVL_PERSISTENT.LimitLegalEnabled;
END_IF;

IF GVL_IHM.Modes.ModeRequest = E_Mode.DISABLE THEN
    GVL_IHM.Modes.ModeRequest := E_Mode.MAINT_N1;
END_IF;


// ── 3. PROPAGATION DES RÉGLAGES IHM → PERSISTANCE ───────────────────────
GVL_PERSISTENT.HomingTargetM1_M           := GVL_IHM.WinchM1.TopSensorPositionM;
GVL_PERSISTENT.HomingTargetM2_M           := GVL_IHM.WinchM2.TopSensorPositionM;
// 🔧 REX 2026-07-08 : MaxStepDescente désormais commun M1/M2 — voir bloc miroir bidirectionnel
// ci-dessous (même pattern que CableLimitDescentM/SlowdownDistanceM/SlowSpeedPct), plus de
// propagation à sens unique séparée par treuil ici.
GVL_PERSISTENT.WinchM1RampAccelRate_Pct   := GVL_IHM.WinchM1.RampAccelRate;
GVL_PERSISTENT.WinchM1RampDecelNormal_Pct := GVL_IHM.WinchM1.RampDecelNormalRate;
GVL_PERSISTENT.WinchM1RampDecelFast_Pct   := GVL_IHM.WinchM1.RampDecelFastRate;
GVL_PERSISTENT.WinchM2RampAccelRate_Pct   := GVL_IHM.WinchM2.RampAccelRate;
GVL_PERSISTENT.WinchM2RampDecelNormal_Pct := GVL_IHM.WinchM2.RampDecelNormalRate;
GVL_PERSISTENT.WinchM2RampDecelFast_Pct   := GVL_IHM.WinchM2.RampDecelFastRate;
// ⚠️ REX 2026-07-08 (5) — PIÈGE pont IHM→PERSISTENT découvert lors de l'audit : cette ligne
// écrase GVL_PERSISTENT.WinchSyncTolerance_M avec GVL_IHM.Sync.SyncToleranceM À CHAQUE SCAN.
// Si on change UNIQUEMENT la valeur par défaut dans GVL_PERSISTENT.st (ou ST_SyncHMI.st), ça ne
// suffit pas : la valeur restaurée au boot (bloc §2 ci-dessus, `IF ... = 0.0 THEN`) ne s'applique
// que si le RETAIN IHM est à 0.0 (premier démarrage) — sinon l'ancienne valeur IHM re-propage ici
// et écrase silencieusement toute nouvelle valeur par défaut au scan suivant.
GVL_PERSISTENT.WinchSyncTolerance_M       := GVL_IHM.Sync.SyncToleranceM;
GVL_PERSISTENT.GrappinConfig              := GVL_IHM.Grappin.Config;

// 🔧 REX 2026-07-08 (demande utilisateur) : MaxStepDescente commun M1/M2 — même profil de
// déplacement des 2 treuils, même pattern miroir que CableLimitDescentM ci-dessous.
IF GVL_IHM.WinchM1.MaxStepDescente <> GVL_PERSISTENT.WinchMaxStepDescente THEN
    GVL_PERSISTENT.WinchMaxStepDescente := GVL_IHM.WinchM1.MaxStepDescente;
